#[instrument(skip(state, message), fields(thread_id = %message.thread_id, message_type = %message.r#type))]
async fn send_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(message): Json<AFPMessage>,
) -> Result<Json<Value>, (StatusCode, String)> {
    enforce_rate_limit(
        &state,
        authenticated_rate_limit_key("send", &headers),
        RateLimitPolicy {
            max_requests: 60,
            window: Duration::from_secs(60),
        },
    )
    .await?;
    let _user = authenticated_user(&state.db, &headers).await?;
    let message_id = store_app_message_for_headers(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &headers,
        message,
    )
    .await?;

    Ok(Json(serde_json::json!({
        "success": true,
        "message_id": message_id
    })))
}

// â”€â”€ Waitlist â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

async fn waitlist_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<WaitlistRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    enforce_rate_limit(
        &state,
        public_rate_limit_key("waitlist", &headers),
        RateLimitPolicy {
            max_requests: 6,
            window: Duration::from_secs(60),
        },
    )
    .await?;
    let email = request.email.trim().to_lowercase();
    if email.is_empty() || !email.contains('@') {
        return Err((
            StatusCode::BAD_REQUEST,
            "valid email is required".to_string(),
        ));
    }

    let waitlist_target =
        std::env::var("OMNYID_WAITLIST_EMAIL").unwrap_or_else(|_| "hello@omnyid.com".to_string());
    let subject = format!("OmnyID waitlist request from {email}");
    let body = format!(
        "Waitlist request received.\n\nEmail: {email}\nSubmitted at: {}\nSource: omnyid.com waitlist form\n",
        chrono::Utc::now().to_rfc3339()
    );

    let request = OutgoingEmailRequest {
        thread_id: format!("waitlist.{}", Ulid::new()),
        message_id: Ulid::new().to_string(),
        parent_id: None,
        to: vec![waitlist_target],
        subject,
        body,
        in_reply_to: None,
        references: vec![],
        attachments: vec![],
    };

    let delivery_result = send_outgoing_email(&request).await;
    let (delivery_status, delivery_error) = match delivery_result {
        Ok(_) => ("sent", None),
        Err(err) => {
            error!(email = %email, error = %err, "Waitlist email delivery failed; storing fallback record");
            ("queued_local_fallback", Some(err))
        }
    };

    let confirmation_request = OutgoingEmailRequest {
        thread_id: format!("waitlist-confirmation.{}", Ulid::new()),
        message_id: Ulid::new().to_string(),
        parent_id: None,
        to: vec![email.clone()],
        subject: "You're on the OmnyID waitlist!".to_string(),
        body: "Congratulations, you're officially on the OmnyID waitlist!\n\n\
OmnyID is a self-hostable, open-source AI agent that keeps track of the bills, forms, dates, and lists cluttering your head, and quietly prepares the next step for each one. Every morning it shows you what needs your attention, what's already ready to review, and what can wait, while your data stays fully under your control.\n\n\
We'll email you as soon as private beta access opens up.\n"
            .to_string(),
        in_reply_to: None,
        references: vec![],
        attachments: vec![],
    };
    if let Err(err) = send_outgoing_email(&confirmation_request).await {
        error!(email = %email, error = %err, "Waitlist confirmation email to requester failed to send");
    }

    state
        .db
        .record_waitlist_submission(&email, delivery_status, delivery_error.as_deref())
        .await
        .map_err(readiness_error_to_http)?;

    Ok(Json(serde_json::json!({
        "status": delivery_status,
        "destination": "hello@omnyid.com",
        "delivery_error": delivery_error
    })))
}

fn is_plausible_email(email: &str) -> bool {
    let Some((local, domain)) = email.split_once('@') else {
        return false;
    };
    !local.is_empty()
        && domain.len() >= 3
        && domain.contains('.')
        && !domain.starts_with('.')
        && !domain.ends_with('.')
        && !email.contains(' ')
}

async fn wedding_waitlist_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<WeddingWaitlistRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    enforce_rate_limit(
        &state,
        public_rate_limit_key("wedding_waitlist", &headers),
        RateLimitPolicy {
            max_requests: 6,
            window: Duration::from_secs(60),
        },
    )
    .await?;

    let email = request.email.trim().to_lowercase();
    if !is_plausible_email(&email) {
        return Err((
            StatusCode::BAD_REQUEST,
            "valid email is required".to_string(),
        ));
    }
    let first_name = request.first_name.trim().to_string();
    let last_name = request.last_name.trim().to_string();
    if first_name.is_empty() || last_name.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            "first and last name are required".to_string(),
        ));
    }
    let expected_wedding_date = request
        .expected_wedding_date
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if let Some(date) = expected_wedding_date {
        if chrono::NaiveDate::parse_from_str(date, "%Y-%m-%d").is_err() {
            return Err((
                StatusCode::BAD_REQUEST,
                "expected_wedding_date must be YYYY-MM-DD".to_string(),
            ));
        }
    }

    let signup = state
        .db
        .insert_wedding_waitlist_signup(&email, &first_name, &last_name, expected_wedding_date)
        .await
        .map_err(readiness_error_to_http)?;

    Ok(Json(serde_json::json!({
        "status": "recorded",
        "signup_id": signup.signup_id
    })))
}

