async fn trial_python_runner_chat_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<TrialChatRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    if let Some(reason) = anonymous_trial_disabled_reason() {
        return Err((StatusCode::SERVICE_UNAVAILABLE, reason));
    }
    enforce_rate_limit(
        &state,
        public_rate_limit_key("trial_python_runner_chat", &headers),
        RateLimitPolicy {
            max_requests: 4,
            window: Duration::from_secs(300),
        },
    )
    .await?;
    let content = request.content.trim();
    if content.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            "trial content is required".to_string(),
        ));
    }
    let identity = trial_identity_key(&headers, request.fingerprint.as_deref());
    let session = state
        .trial_runner
        .append_chat_turn(&request.session_id, content, &identity, &state.db.pool, &state.http_client)
        .await
        .map_err(|err| {
            if err.contains("not found") {
                (StatusCode::NOT_FOUND, err)
            } else if err.contains("sign up") {
                (StatusCode::PAYMENT_REQUIRED, err)
            } else {
                (StatusCode::BAD_REQUEST, err)
            }
        })?;
    Ok(Json(trial_session_response(&session)))
}

