fn multi_replica_mode_enabled() -> bool {
    std::env::var("OMNYID_MULTI_REPLICA_MODE")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

fn allow_local_trial_in_multi_replica() -> bool {
    std::env::var("OMNYID_ALLOW_LOCAL_TRIALS_IN_MULTI_REPLICA")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

fn anonymous_trial_disabled_reason() -> Option<String> {
    if !multi_replica_mode_enabled() || allow_local_trial_in_multi_replica() {
        return None;
    }
    Some(
        "Anonymous interactive trial is disabled while OMNYID_MULTI_REPLICA_MODE=1 because trial sessions are process-local. Sign in, run a single homeserver replica, or explicitly opt back in with OMNYID_ALLOW_LOCAL_TRIALS_IN_MULTI_REPLICA=1 plus sticky sessions."
            .to_string(),
    )
}

// â”€â”€ Dashboard â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

async fn demo_send_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<DemoSendRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    enforce_rate_limit(
        &state,
        authenticated_rate_limit_key("demo_send", &headers),
        RateLimitPolicy {
            max_requests: 20,
            window: Duration::from_secs(60),
        },
    )
    .await?;
    let user = authenticated_user(&state.db, &headers).await?;
    let agents = state
        .db
        .list_managed_agents_by_user(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let owns_from = agents
        .iter()
        .any(|agent| agent.agent_id == request.from_agent_id);
    let owns_to = agents
        .iter()
        .any(|agent| agent.agent_id == request.to_agent_id);
    if !owns_from || !owns_to {
        return Err((
            StatusCode::FORBIDDEN,
            "selected agents are not managed by this account".to_string(),
        ));
    }

    let thread_id = demo_thread_id(&user.id);
    let message = new_server_message(
        request.from_agent_id,
        vec![request.to_agent_id],
        thread_id,
        "agent_message",
        serde_json::json!({
            "body": request.body.trim(),
            "kind": "demo_message"
        }),
        vec![serde_json::json!({
            "format": "email",
            "content": {
                "subject": "Demo agent message",
                "body": request.body.trim(),
            }
        })],
        vec![],
        vec![],
        true,
    )
    .map_err(internal_http_error)?;
    let message_id = message.id.clone();

    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        message,
    )
    .await
    .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "success": true,
        "message_id": message_id
    })))
}

// â”€â”€ Notes message endpoint â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/// Accepted `type` values for the notes message endpoint.
const NOTES_ALLOWED_TYPES: &[&str] = &[
    "note",
    crate::message::AFP_TYPE_FOLDER_RULE,
    crate::message::AFP_TYPE_AREA_RULES,
    crate::message::AFP_TYPE_TAG_UPDATE,
];

#[derive(serde::Deserialize)]
struct NoteMessageRequest {
    /// AFP message type: "note", "folder_rule", "area_rules", or "tag_update".
    r#type: String,
    #[serde(default)]
    kind: Option<String>,
    /// Thread to append to. For note messages this is the note thread.
    /// For folder/area rules this is the folder/area id;
    /// for tag_update it should match the source note's thread_id.
    thread_id: String,
    /// Message content. Shape varies by type.
    content: serde_json::Value,
    /// For `note` and `tag_update`: ids of the original note messages being updated.
    #[serde(default)]
    references: Vec<serde_json::Value>,
}

async fn notes_message_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(req): Json<NoteMessageRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    if !NOTES_ALLOWED_TYPES.contains(&req.r#type.as_str()) {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            format!("type must be one of: {}", NOTES_ALLOWED_TYPES.join(", ")),
        ));
    }

    let user = authenticated_user(&state.db, &headers).await?;

    let agents = state
        .db
        .list_managed_agents_by_user(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    // Use the user's first managed agent, or derive a stable notes agent id.
    let from_agent = agents
        .first()
        .map(|a| a.agent_id.clone())
        .unwrap_or_else(|| format!("agent:notes@{}", user.id));

    let message = new_server_message(
        from_agent,
        vec![],
        req.thread_id,
        &req.r#type,
        req.content,
        vec![],
        req.references,
        vec![],
        true,
    )
    .map_err(internal_http_error)?;

    let message_id = message.id.clone();

    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        message,
    )
    .await
    .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "success": true,
        "message_id": message_id
    })))
}

