fn execute_trial_tools(
    content: &str,
    tool_policy: &Value,
) -> (Vec<TrialTraceEntry>, Vec<TrialReviewItem>) {
    let mut traces = Vec::new();
    let mut reviews = Vec::new();
    let lowered = content.to_lowercase();

    let mut push_trace =
        |tool: &str, status: &str, blocked_reason: Option<&str>, host: Option<&str>| {
            traces.push(TrialTraceEntry {
                timestamp: chrono::Utc::now().to_rfc3339(),
                tool: tool.to_string(),
                status: status.to_string(),
                blocked_reason: blocked_reason.map(str::to_string),
                host: host.map(str::to_string),
            });
        };

    let tool_enabled = |tool: &str| -> bool {
        tool_policy
            .get(tool)
            .and_then(|entry| entry.get("enabled"))
            .and_then(Value::as_bool)
            .unwrap_or(false)
    };

    if lowered.contains("http://")
        || lowered.contains("https://")
        || lowered.contains("website")
        || lowered.contains("search")
    {
        push_trace(
            "web",
            if tool_enabled("web") {
                "allowed"
            } else {
                "blocked"
            },
            (!tool_enabled("web")).then_some("tool_disabled"),
            Some("api.omnyid.com"),
        );
    }
    if lowered.contains("agent:") || lowered.contains("relay") || lowered.contains("send to") {
        push_trace(
            "afp_agent",
            if tool_enabled("afp_agent") {
                "allowed"
            } else {
                "blocked"
            },
            (!tool_enabled("afp_agent")).then_some("tool_disabled"),
            None,
        );
    }
    if lowered.contains("book")
        || lowered.contains("payment")
        || lowered.contains("charge")
        || lowered.contains("refund")
    {
        let allowed = tool_enabled("stripe");
        push_trace(
            "stripe",
            if allowed { "allowed" } else { "blocked" },
            (!allowed).then_some("tool_disabled"),
            Some("api.stripe.com"),
        );
        reviews.push(TrialReviewItem {
            id: format!("review-{}", Ulid::new()),
            tool: "stripe".to_string(),
            status: "review_required".to_string(),
            reason: "Booking and payment paths always require a human review step.".to_string(),
            created_at: chrono::Utc::now().to_rfc3339(),
        });
    }
    (traces, reviews)
}

fn trial_meta_summary(traces: &[TrialTraceEntry], reviews: &[TrialReviewItem]) -> String {
    let trace_summary = if traces.is_empty() {
        "Reasoning step complete.".to_string()
    } else {
        format!(
            "Tool plan: {}",
            traces
                .iter()
                .map(|trace| format!("{} ({})", trace.tool, trace.status))
                .collect::<Vec<_>>()
                .join(", ")
        )
    };
    if reviews.is_empty() {
        trace_summary
    } else {
        format!("{trace_summary}\nSensitive action queued for human review.")
    }
}

/// Generates a bounded trial reply through the shared funded OpenRouter gate.
/// The confirm reply remains deterministic because it changes preview state.
async fn trial_generate_reply(
    pool: &sqlx::PgPool,
    client: &reqwest::Client,
    identity_key: &str,
    content: &str,
    template: &TrialTemplate,
    traces: &[TrialTraceEntry],
    reviews: &[TrialReviewItem],
    intent: &str,
    history: &[TrialChatMessage],
) -> String {
    if intent == "confirm" {
        return trial_assistant_reply(content, template, traces, reviews, intent);
    }
    let system = format!(
        "{} This is an anonymous, ephemeral product trial. Never claim to book, pay, sync, or persist anything. For travel requests, produce a useful day-by-day itinerary with reasons, practical map links and month-appropriate weather guidance. Respect the requested month and year. Never invent flight, hotel, booking or clock times. Distinguish climate guidance from a live forecast.",
        template.system_prompt
    );
    let conversation = history
        .iter()
        .filter(|message| message.role == "user" || message.role == "assistant")
        .rev().take(6).collect::<Vec<_>>().into_iter().rev()
        .map(|message| format!("{}: {}", message.role, message.content))
        .collect::<Vec<_>>();
    let prompt = conversation.join("\n\n");
    match openrouter_funded_inference::infer(pool, client, openrouter_funded_inference::FundedInferenceRequest {
        feature: "public_trial_runner",
        user_id: None,
        wedding_plan_id: None,
        abuse_id: identity_key,
        system: &system,
        prompt: &prompt,
        max_tokens: 800,
        json_mode: false,
    }).await {
        Ok(response) => {
            let meta = trial_meta_summary(traces, reviews);
            if meta.is_empty() {
                response.content
            } else {
                format!("{}\n\n{meta}", response.content.trim())
            }
        }
        Err(err) => {
            tracing::warn!(error = %err, "funded trial inference unavailable; using bounded fallback");
            trial_assistant_reply(content, template, traces, reviews, intent)
        }
    }
}

fn trial_assistant_reply(
    content: &str,
    template: &TrialTemplate,
    traces: &[TrialTraceEntry],
    reviews: &[TrialReviewItem],
    intent: &str,
) -> String {
    if intent == "confirm" {
        return "Draft reviewed. It has been added to this preview session's calendar view only.\n\n- Flight arrival at 2:00 pm\n- Hotel check-in at 4:00 pm\n- Free time from 5:00 pm\n\nNothing has been booked, synced, or saved outside the anonymous trial.".to_string();
    }

    let lowered = content.to_lowercase();
    let meta = trial_meta_summary(traces, reviews);

    if template.id == "student_day_planner" {
        let source_label = if lowered.contains("assignment") || lowered.contains("essay") {
            "assignment brief"
        } else if lowered.contains("reading") || lowered.contains("author") {
            "reading excerpt"
        } else if lowered.contains("lecture") || lowered.contains("professor") {
            "lecture notes"
        } else {
            "study source"
        };
        return format!(
            "{}\n\n{}\n\nConnected notes preview from your {}\n\n1. Core concepts: extract the main terms, definitions, and examples first so the answer is grounded in the student's own material.\n2. Links to build: connect repeated concepts, weak points, course/week cues, and exam or assignment risks through supertags.\n3. Next study move: choose one narrow follow-up from the same topic so the thread becomes easier to retrieve later.\n\nIn the signed-in workspace, OmnyID would offer to keep the original file, keep extracted study content only, or keep nothing. The recommended student default is extracted content only, because it preserves searchable notes, supertags, and graph links without storing the raw file by default.",
            template.name, meta, source_label,
        );
    }

    if intent == "schedule" {
        return [
            "Trip Planner · Three-day Sydney draft",
            "",
            "Day 1 — Circular Quay, The Rocks and the Royal Botanic Garden. Start with the harbour landmarks and an easy waterfront walk so the first day stays flexible after arrival.",
            "Map: https://www.google.com/maps/search/?api=1&query=Circular+Quay+Sydney",
            "",
            "Day 2 — Bondi to Coogee coastal walk, with the Art Gallery of NSW as a wet-weather alternative. This gives you the coast without spending the whole day in transit.",
            "Map: https://www.google.com/maps/search/?api=1&query=Bondi+to+Coogee+Walk",
            "",
            "Day 3 — Ferry to Manly, then a relaxed harbour-side afternoon. The ferry is part of the experience and keeps the final day easy to shorten if needed.",
            "Map: https://www.google.com/maps/search/?api=1&query=Manly+Wharf",
            "",
            "January is typically warm and can be humid, but a live forecast is not reliable this far ahead. Check the Bureau of Meteorology closer to travel: https://www.bom.gov.au/nsw/forecasts/sydney.shtml",
            "",
            "No flight, hotel or clock time was assumed. Add those only when you know them.",
        ].join("\n");
    }

    let bullets = if template.id == "travel_planner"
        || lowered.contains("trip")
        || lowered.contains("itinerary")
        || lowered.contains("flight")
    {
        vec![
            "1. Lock in the fixed bookings first (flights, check-in times), then place everything else around them.",
            "2. Keep one flexible backup ready in case of weather or delays.",
            "3. End each day with tomorrow's first move already decided.",
        ]
    } else if template.id == "appointment_assistant"
        || lowered.contains("appointment")
        || lowered.contains("booking")
    {
        vec![
            "1. Confirm the time, location, and what you need to bring.",
            "2. Prepare the reminder or reschedule steps before touching a live booking flow.",
            "3. Queue any payment or booking action for review instead of auto-executing it.",
        ]
    } else if template.id == "student_day_planner"
        || lowered.contains("study")
        || lowered.contains("lecture")
        || lowered.contains("exam")
        || lowered.contains("assignment")
        || lowered.contains("notes")
    {
        vec![
            "1. Ground the answer in the student's own lecture, reading, note, or transcript context first.",
            "2. Pull out the main concepts, overlaps, and likely weak points instead of repeating the source verbatim.",
            "3. End with the smallest next study step that reduces pressure now and would normally compound into connected notes later.",
        ]
    } else {
        vec![
            "1. Clarify the goal, deadline, and minimum useful output.",
            "2. Decide whether this needs web research, a question back, or a simple next action.",
            "3. Capture the next action so the result can be replayed later.",
        ]
    };

    format!("{}\n\n{}\n\n{}", template.name, meta, bullets.join("\n"))
}

fn build_trial_calendar_view(content: &str) -> Value {
    let lowered = content.to_lowercase();
    let num_flights = if lowered.contains("two")
        || lowered.contains(" 2 ")
        || lowered.contains("connecting")
        || lowered.contains("layover")
    {
        2usize
    } else {
        1
    };
    let has_hotel =
        lowered.contains("hotel") || lowered.contains("check-in") || lowered.contains("checkin");
    let start_hour: u32 = 14;
    let end_hour: u32 = 24;

    let mut slots = Vec::new();
    let mut current = start_hour;

    for i in 0..num_flights {
        slots.push(serde_json::json!({
            "start": format!("{:02}:00", current),
            "end": format!("{:02}:00", current + 1),
            "label": if i == 0 { "Flight arrival".to_string() } else { "Connecting flight".to_string() },
            "type": "flight",
            "movable": true
        }));
        current += 1;
    }
    if has_hotel {
        slots.push(serde_json::json!({
            "start": format!("{:02}:00", current),
            "end": format!("{:02}:00", current + 1),
            "label": "Hotel check-in",
            "type": "lodging",
            "movable": true
        }));
        current += 1;
    }
    if current < end_hour {
        slots.push(serde_json::json!({
            "start": format!("{:02}:00", current),
            "end": "24:00",
            "label": "Free time",
            "type": "free",
            "movable": false
        }));
    }

    serde_json::json!({
        "start_hour": start_hour,
        "end_hour": end_hour,
        "slots": slots,
        "preview_notice": "Preview only. Review this draft before adding it to your preview calendar. No booking or external action happens automatically in the anonymous trial.",
        "pending_confirmation": true,
        "confirmed": false
    })
}

fn trial_session_response(session: &TrialRunnerSession) -> Value {
    serde_json::json!({
        "session_id": session.id,
        "created_at": session.created_at,
        "expires_at": session.expires_at,
        "active_template_id": session.active_template_id,
        "runs_started": session.runs_started,
        "max_runs": session.max_runs,
        "turns_used": session.turns_used,
        "max_turns": session.max_turns,
        "remaining_runs": session.max_runs.saturating_sub(session.runs_started),
        "remaining_turns": session.max_turns.saturating_sub(session.turns_used),
        "requires_signup": session.requires_signup,
        "messages": session.messages,
        "logs": session.logs,
        "traces": session.traces,
        "prompt_versions": session.prompt_versions,
        "saved_tests": session.saved_tests,
        "review_queue": session.review_queue,
        "model_policy": session.model_policy,
        "tool_policy": session.tool_policy,
        "channel_policy": session.channel_policy,
        "starter_templates": session.starter_templates,
        "last_good_run": session.last_good_run,
        "calendar_view": session.calendar_view,
    })
}

fn build_runtime_deployment_plan(
    user: &UserRecord,
    agents: &[ManagedAgentRecord],
    framework: &str,
    gui: Option<&str>,
) -> Result<RuntimeDeploymentRecord, (StatusCode, String)> {
    let (framework_name, default_gui, image_ref, python_version, notes, capabilities) =
        match framework {
            "crewai" => (
                "crewai",
                "crewai-studio",
                "python:3.13-slim",
                "3.13",
                vec![
                    "This deployment record is a private per-user Crew runtime plan.",
                    "Actual runtime orchestration must preserve isolated secrets, logs, storage, and message scope.",
                    "This runtime scaffold is safe to materialize because it is per-user and does not mix messages or secrets.",
                ],
                serde_json::json!({
                    "telemetry_disabled": true,
                    "share_crew": false,
                    "gui": "CrewAI-Studio community project",
                    "gui_license": "MIT",
                    "bring_your_own_llm_key": true,
                }),
            ),
            "python-runner-chat" => (
                "python-runner-chat",
                "builtin-chat-window",
                "python:3.13-slim-bookworm",
                "3.13",
                vec![
                    "This deployment record is a private per-user Python runner with a built-in chat window.",
                    "It is intended for Coolify-style one-click hosting with OmnyID-managed model defaults and optional BYOK after signup.",
                    "The chat window is a private control surface for the isolated runtime, not a shared operator console.",
                    "The runtime scaffold carries CPU, memory, pids, runtime, and egress policy defaults for non-technical users.",
                ],
                serde_json::json!({
                    "telemetry_disabled": true,
                    "share_runner": false,
                    "gui": "Built-in lightweight chat window and agent IDE",
                    "gui_license": "OmnyID runtime scaffold",
                    "bring_your_own_llm_key": true,
                    "omnyid_managed_model_access": true,
                    "coolify_ready": true,
                }),
            ),
            _ => return Err((StatusCode::BAD_REQUEST, "unsupported framework".to_string())),
        };

    let safe_gui = gui
        .filter(|value| !value.trim().is_empty())
        .map(|value| value.to_string())
        .or_else(|| Some(default_gui.to_string()));
    let now = chrono::Utc::now().to_rfc3339();
    let user_slug = email_localpart_slug(&user.email);
    let runtime_id = Ulid::new().to_string();
    let workspace_root = runtime_root();
    let workspace_path = format!(
        "{root}/{user_slug}-{id}",
        root = workspace_root.display(),
        id = &user.id[..8]
    );
    let runtime_token = random_token();
    let primary_agent_id = agents
        .first()
        .map(|agent| agent.agent_id.clone())
        .unwrap_or_else(|| format!("agent:{user_slug}@omnyid.com"));
    let runtime_mode = "signed_in_hosted";
    let runtime_cpu_limit = "1.0";
    let runtime_memory_limit = "1536m";
    let runtime_pids_limit = 256;
    let runtime_max_seconds = 120;
    let background_runtime_max_seconds = 900;
    let gui_name = safe_gui
        .clone()
        .unwrap_or_else(|| default_runtime_gui(framework_name).to_string());

    Ok(RuntimeDeploymentRecord {
        id: runtime_id,
        owner_user_id: user.id.clone(),
        framework: framework_name.to_string(),
        gui: safe_gui,
        status: "planned".to_string(),
        python_version: python_version.to_string(),
        image_ref: image_ref.to_string(),
        runtime_token: runtime_token.clone(),
        workspace_path: workspace_path.clone(),
        config_json: serde_json::json!({
            "privacy_mode": "isolated_per_user",
            "telemetry_disabled": true,
            "share_crew": false,
            "share_runner": false,
            "runtime_template_version": runtime_template_version(),
            "agent_scope": {
                "owner_user_id": user.id,
                "owner_email": user.email,
            },
            "runtime_family": framework_name,
            "runtime_root": workspace_root.display().to_string(),
            "scaffold": {
                "status": "materialized",
                "compose_file": format!("{workspace_path}/docker-compose.yml"),
                "env_file": format!("{workspace_path}/.env"),
                "workspace_dir": format!("{workspace_path}/workspace"),
                "logs_dir": format!("{workspace_path}/logs"),
                "entrypoint": format!(
                    "{workspace_path}/workspace/{}",
                    runtime_entrypoint_filename(framework_name)
                ),
                "agent_profile": format!("{workspace_path}/workspace/agent_profile.json"),
            },
            "notes": notes,
            "runtime_env": {
                "OMNYID_RUNTIME_TOKEN": runtime_token,
                "OMNYID_OWNER_USER_ID": user.id,
                "OMNYID_OWNER_EMAIL": user.email,
            },
            "starter_profile": {
                "primary_agent_id": primary_agent_id,
                "gui_name": gui_name,
                "default_template_id": "travel_planner",
            },
            "runtime_mode": runtime_mode,
            "sandbox_policy": default_runner_sandbox_policy(framework_name),
            "resource_policy": default_runner_resource_policy(
                framework_name,
                runtime_cpu_limit,
                runtime_memory_limit,
                runtime_pids_limit,
                runtime_max_seconds,
                background_runtime_max_seconds,
            ),
            "network_policy": default_runner_network_policy(framework_name),
            "model_policy": default_runner_model_policy(framework_name),
            "tool_policy": default_runner_tool_policy(framework_name),
            "channel_policy": default_runner_channel_policy(framework_name),
            "starter_templates": default_runner_templates(framework_name),
            "governance": default_runner_governance(framework_name),
            "audit_scope": default_runner_audit_scope(framework_name),
            "capabilities": capabilities,
        }),
        created_at: now.clone(),
        updated_at: now,
    })
}

fn default_runner_sandbox_policy(framework: &str) -> Value {
    if framework != "python-runner-chat" {
        return serde_json::json!({});
    }
    serde_json::json!({
        "runtime_isolation": "per_workspace_container",
        "run_as_non_root": true,
        "read_only_root_filesystem": true,
        "no_new_privileges": true,
        "cap_drop": ["ALL"],
        "seccomp_profile": "docker-default",
        "apparmor_profile": "docker-default",
        "docker_socket_mount": false,
        "host_networking": false,
        "writable_mounts": [
            "/workspace/data/files",
            "/workspace/data/db",
            "/workspace/data/vector",
            "/workspace/logs",
            "/tmp"
        ]
    })
}

fn default_runner_resource_policy(
    framework: &str,
    cpu_limit: &str,
    memory_limit: &str,
    pids_limit: i32,
    interactive_max_seconds: i32,
    background_max_seconds: i32,
) -> Value {
    if framework != "python-runner-chat" {
        return serde_json::json!({});
    }
    serde_json::json!({
        "interactive": {
            "cpu_limit": cpu_limit,
            "memory_limit": memory_limit,
            "pids_limit": pids_limit,
            "max_runtime_seconds": interactive_max_seconds
        },
        "background": {
            "max_runtime_seconds": background_max_seconds
        },
        "recycle_policy": {
            "recycle_after_hours": 24,
            "recycle_after_runs": 100
        }
    })
}

