pub(super) fn runtime_token_preview(token: &str) -> String {
    if token.len() <= 8 {
        return "redacted".to_string();
    }

    format!("{}...{}", &token[..4], &token[token.len() - 4..])
}

fn account_session_ref(token_hash: &str) -> String {
    token_hash.to_string()
}

fn write_runtime_file(path: &std::path::Path, content: &str) -> Result<(), String> {
    std::fs::write(path, content)
        .map_err(|err| format!("failed to write {}: {err}", path.display()))
}

fn render_runtime_template(template: &str, values: &BTreeMap<&str, String>) -> String {
    let mut rendered = template.to_string();
    for (key, value) in values {
        let placeholder = format!("{{{{{key}}}}}");
        rendered = rendered.replace(&placeholder, value);
    }
    rendered
}

fn default_onboarding_for_user(user: &UserRecord) -> UserOnboardingRecord {
    UserOnboardingRecord {
        owner_user_id: user.id.clone(),
        identity_confirmed: false,
        email_provider: None,
        email_address: Some(user.email.clone()),
        email_connected: false,
        llm_mode: "byo_or_local".to_string(),
        notes: serde_json::json!({
            "source": "default",
            "next_step": "complete_setup"
        }),
        updated_at: chrono::Utc::now().to_rfc3339(),
        completed_at: None,
    }
}

fn build_onboarding_record(
    user: &UserRecord,
    request: OnboardingUpdateRequest,
) -> Result<UserOnboardingRecord, (StatusCode, String)> {
    let email_provider = request
        .email_provider
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_lowercase);
    let email_address = request
        .email_address
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let llm_mode = request
        .llm_mode
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("byo_or_local")
        .to_string();

    if request.email_connected {
        if email_provider.is_none() {
            return Err((
                StatusCode::BAD_REQUEST,
                "email provider is required".to_string(),
            ));
        }
        if email_address
            .as_deref()
            .is_none_or(|value| !value.contains('@'))
        {
            return Err((
                StatusCode::BAD_REQUEST,
                "valid email address is required".to_string(),
            ));
        }
    }

    let completed_at = if request.identity_confirmed {
        Some(chrono::Utc::now().to_rfc3339())
    } else {
        None
    };

    Ok(UserOnboardingRecord {
        owner_user_id: user.id.clone(),
        identity_confirmed: request.identity_confirmed,
        email_provider,
        email_address,
        email_connected: request.email_connected,
        llm_mode,
        notes: request.notes.unwrap_or_else(|| serde_json::json!({})),
        updated_at: chrono::Utc::now().to_rfc3339(),
        completed_at,
    })
}

/// Middleware: generate or propagate X-Request-ID for distributed tracing (GAP-080).
async fn request_id_middleware(
    req: axum::extract::Request,
    next: axum::middleware::Next,
) -> axum::response::Response {
    let req_id = req
        .headers()
        .get("x-request-id")
        .and_then(|v| v.to_str().ok())
        .map(str::to_string)
        .unwrap_or_else(|| ulid::Ulid::new().to_string());

    let span = tracing::info_span!("request", request_id = %req_id);
    let _guard = span.enter();

    let mut response = next.run(req).await;
    if let Ok(hv) = axum::http::HeaderValue::from_str(&req_id) {
        response.headers_mut().insert("x-request-id", hv);
    }
    response
}

pub(super) fn internal_error(err: sqlx::Error) -> Status {
    // Log full error internally but never return raw DB details to clients (GAP-079).
    tracing::error!(error = %err, "database error");
    match &err {
        sqlx::Error::RowNotFound => Status::not_found("record not found"),
        _ => Status::internal("internal server error"),
    }
}

pub(super) fn readiness_error_to_http(err: SqlxError) -> (StatusCode, String) {
    tracing::error!(error = %err, "readiness check database error");
    (
        StatusCode::SERVICE_UNAVAILABLE,
        "database unavailable".to_string(),
    )
}

pub(super) fn status_to_http(status: Status) -> (StatusCode, String) {
    let code = match status.code() {
        tonic::Code::InvalidArgument => StatusCode::BAD_REQUEST,
        tonic::Code::NotFound => StatusCode::NOT_FOUND,
        tonic::Code::Unauthenticated => StatusCode::UNAUTHORIZED,
        _ => StatusCode::INTERNAL_SERVER_ERROR,
    };
    (code, status.message().to_string())
}

pub(super) fn task_update_error_to_http(err: sqlx::Error) -> (StatusCode, String) {
    if matches!(&err, sqlx::Error::RowNotFound) {
        (StatusCode::NOT_FOUND, "task not found".to_string())
    } else {
        status_to_http(internal_error(err))
    }
}

fn trigger_delete_error_to_http(err: sqlx::Error) -> (StatusCode, String) {
    if matches!(&err, sqlx::Error::RowNotFound) {
        (StatusCode::NOT_FOUND, "trigger not found".to_string())
    } else {
        status_to_http(internal_error(err))
    }
}

fn delegation_revoke_error_to_http(err: sqlx::Error) -> (StatusCode, String) {
    if matches!(&err, sqlx::Error::RowNotFound) {
        (StatusCode::NOT_FOUND, "delegation not found".to_string())
    } else {
        status_to_http(internal_error(err))
    }
}

fn startup_environment_label() -> Option<String> {
    [
        "OMNYID_ENV",
        "APP_ENV",
        "ENVIRONMENT",
        "RUST_ENV",
        "NODE_ENV",
    ]
    .iter()
    .find_map(|key| {
        std::env::var(key)
            .ok()
            .map(|value| value.trim().to_ascii_lowercase())
            .filter(|value| !value.is_empty())
    })
}

fn production_startup_policy_enabled() -> bool {
    matches!(
        startup_environment_label().as_deref(),
        Some("prod" | "production")
    )
}

fn env_flag_enabled(name: &str) -> bool {
    std::env::var(name)
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(false)
}

fn database_url_looks_like_dev_default(database_url: &str) -> bool {
    matches!(
        database_url.trim(),
        "" | "postgres://afp:afp@postgres:5432/afp" | "postgres://afp:afp@localhost:5432/afp"
    )
}

fn env_var_present(name: &str) -> bool {
    std::env::var(name)
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn stripe_secret_key_looks_valid(value: &str) -> bool {
    let trimmed = value.trim();
    (trimmed.starts_with("sk_live_")
        || trimmed.starts_with("sk_test_")
        || trimmed.starts_with("rk_live_")
        || trimmed.starts_with("rk_test_"))
        && trimmed.len() > "rk_test_".len()
}

fn stripe_webhook_secret_looks_valid(value: &str) -> bool {
    let trimmed = value.trim();
    trimmed.starts_with("whsec_") && trimmed.len() > "whsec_".len()
}

fn stripe_price_id_looks_valid(value: &str) -> bool {
    let trimmed = value.trim();
    trimmed.starts_with("price_") && trimmed.len() > "price_".len()
}

fn stripe_production_config_present() -> bool {
    [
        "OMNYID_STRIPE_SECRET_KEY",
        "OMNYID_STRIPE_WEBHOOK_SECRET",
        "OMNYID_STRIPE_PRO_PRICE_ID",
        "OMNYID_STRIPE_CHECKOUT_PRICE_ID",
        "OMNYID_STRIPE_TEAM_PRICE_ID",
        "OMNYID_STRIPE_WEDDING_PRODUCT_ID",
        "STRIPE_SECRET_KEY",
        "STRIPE_PRO_PRICE_ID",
        "STRIPE_CHECKOUT_PRICE_ID",
        "STRIPE_PRODUCT_ID",
        "OMNYID_WORKSPACE_BASE_URL",
        "OMNYID_UI_BASE_URL",
    ]
    .iter()
    .any(|name| env_var_present(name))
}

fn public_operational_endpoints_enabled() -> bool {
    env_flag_enabled("OMNYID_PUBLIC_OPERATIONAL_ENDPOINTS")
}

fn validate_startup_deployment_policy() -> Result<(), String> {
    if !production_startup_policy_enabled() {
        return Ok(());
    }

    let mut violations = Vec::new();

    if env_flag_enabled("OMNYID_ALLOW_INSECURE_UNSIGNED") {
        violations.push("OMNYID_ALLOW_INSECURE_UNSIGNED must be false in production".to_string());
    }
    if env_flag_enabled("OMNYID_ALLOW_PLAINTEXT_STORAGE") {
        violations.push("OMNYID_ALLOW_PLAINTEXT_STORAGE must be false in production".to_string());
    }

    let database_url = std::env::var("DATABASE_URL").unwrap_or_default();
    if database_url_looks_like_dev_default(&database_url) {
        violations
            .push("DATABASE_URL must be set to a non-default production database".to_string());
    }

    if let Err(err) = crate::agent_template::delegation_master_key_hex() {
        violations.push(err);
    }

    let gmail_oauth_status = self::health_deps::check_gmail_oauth_readiness();
    if gmail_oauth_status != "ok" && gmail_oauth_status != "not_configured" {
        violations.push(format!(
            "Gmail OAuth must be fully configured in production when enabled ({gmail_oauth_status})"
        ));
    }

    if stripe_production_config_present() {
        let stripe_secret = crate::secret_manager::read_process_secret_trimmed(
            "OMNYID_STRIPE_SECRET_KEY",
        )
        .or_else(|| crate::secret_manager::read_process_secret_trimmed("STRIPE_SECRET_KEY"))
        .unwrap_or_default();
        if !stripe_secret_key_looks_valid(&stripe_secret) {
            violations.push(
                "OMNYID_STRIPE_SECRET_KEY must be set to a valid Stripe secret key when self-serve billing is configured".to_string(),
            );
        }

        let webhook_secret = crate::secret_manager::read_process_secret_trimmed(
            "OMNYID_STRIPE_WEBHOOK_SECRET",
        )
        .unwrap_or_default();
        if !stripe_webhook_secret_looks_valid(&webhook_secret) {
            violations.push(
                "OMNYID_STRIPE_WEBHOOK_SECRET must be set to a valid Stripe webhook secret when self-serve billing is configured".to_string(),
            );
        }

        if self::billing::stripe_checkout_reference_for_plan("pro").is_none() {
            violations.push(
                "a valid Stripe Wedding product or price must be configured when self-serve billing is configured".to_string(),
            );
        }

        if let Ok(team_price) = std::env::var("OMNYID_STRIPE_TEAM_PRICE_ID")
            && !team_price.trim().is_empty()
            && !stripe_price_id_looks_valid(&team_price)
        {
            violations.push(
                "OMNYID_STRIPE_TEAM_PRICE_ID must be a valid Stripe price id when set".to_string(),
            );
        }

        if !self::billing::billing_workspace_base_url_is_configured() {
            violations.push(
                "OMNYID_WORKSPACE_BASE_URL, OMNYID_UI_BASE_URL, or a derivable OMNYID_HOMESERVER_URL must be configured when self-serve billing is enabled".to_string(),
            );
        }
    }

    if public_operational_endpoints_enabled()
        && crate::secret_manager::read_process_secret_trimmed("OMNYID_OPERATIONAL_ENDPOINT_TOKEN")
            .is_none()
    {
        violations.push(
            "OMNYID_OPERATIONAL_ENDPOINT_TOKEN must be configured when OMNYID_PUBLIC_OPERATIONAL_ENDPOINTS is enabled in production".to_string(),
        );
    }

    if violations.is_empty() {
        Ok(())
    } else {
        Err(violations.join("; "))
    }
}

fn allow_insecure_unsigned_messages() -> bool {
    std::env::var("OMNYID_ALLOW_INSECURE_UNSIGNED")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

pub(super) fn sign_server_generated_message(message: &mut AFPMessage) -> Result<(), String> {
    let Some(seed) = env_hex_32("OMNYID_SIGNING_KEY_HEX")? else {
        if allow_insecure_unsigned_messages() {
            return Ok(());
        }
        return Err(
            "OMNYID_SIGNING_KEY_HEX must be configured for server-generated approval messages"
                .to_string(),
        );
    };

    sign_message(message, &seed);
    Ok(())
}

fn action_status_json_label(status: &ActionStatus) -> &'static str {
    match status {
        ActionStatus::Pending => "pending",
        ActionStatus::Approved => "approved",
        ActionStatus::Rejected => "rejected",
        ActionStatus::Completed => "completed",
        ActionStatus::Failed => "failed",
    }
}

pub(super) fn env_hex_32(name: &str) -> Result<Option<[u8; 32]>, String> {
    let value = std::env::var(name).unwrap_or_default();
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }

    let bytes = hex::decode(trimmed).map_err(|_| format!("{name} must be valid hex"))?;
    let array: [u8; 32] = bytes
        .try_into()
        .map_err(|_| format!("{name} must decode to 32 bytes"))?;
    Ok(Some(array))
}

fn require_encryption() -> bool {
    std::env::var("OMNYID_REQUIRE_ENCRYPTION")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

pub(super) fn enable_internal_grpc() -> bool {
    std::env::var("OMNYID_ENABLE_INTERNAL_GRPC")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

pub(super) fn webtransport_enabled() -> bool {
    if !std::env::var("OMNYID_ENABLE_WEBTRANSPORT")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
    {
        return false;
    }

    webtransport_cert_path().is_some() && webtransport_key_path().is_some()
}

fn grpc_bind_addr() -> SocketAddr {
    std::env::var("OMNYID_INTERNAL_GRPC_ADDR")
        .ok()
        .and_then(|value| value.parse::<SocketAddr>().ok())
        .unwrap_or_else(|| "127.0.0.1:50051".parse().expect("valid grpc bind addr"))
}

fn http_bind_addr() -> SocketAddr {
    std::env::var("OMNYID_HTTP_BIND_ADDR")
        .ok()
        .and_then(|value| value.trim().parse::<SocketAddr>().ok())
        .unwrap_or_else(|| "0.0.0.0:8080".parse().expect("valid HTTP bind addr"))
}

pub(super) fn webtransport_bind_addr() -> SocketAddr {
    std::env::var("OMNYID_WEBTRANSPORT_BIND_ADDR")
        .ok()
        .and_then(|value| value.parse::<SocketAddr>().ok())
        .unwrap_or_else(|| {
            "0.0.0.0:8443"
                .parse()
                .expect("valid WebTransport bind addr")
        })
}

fn webtransport_cert_path() -> Option<String> {
    std::env::var("OMNYID_WEBTRANSPORT_CERT_PATH")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn webtransport_key_path() -> Option<String> {
    std::env::var("OMNYID_WEBTRANSPORT_KEY_PATH")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

pub(super) async fn load_webtransport_identity() -> Result<WebTransportIdentity, String> {
    let cert_path = webtransport_cert_path()
        .ok_or_else(|| "OMNYID_WEBTRANSPORT_CERT_PATH must be set".to_string())?;
    let key_path = webtransport_key_path()
        .ok_or_else(|| "OMNYID_WEBTRANSPORT_KEY_PATH must be set".to_string())?;

    WebTransportIdentity::load_pemfiles(cert_path, key_path)
        .await
        .map_err(|err| err.to_string())
}

fn has_encryption_envelope(message: &Message) -> bool {
    let trimmed = message.encryption.trim();
    !(trimmed.is_empty() || trimmed == "{}" || trimmed == "null")
}

fn has_supported_encryption_envelope(message: &Message) -> bool {
    if !has_encryption_envelope(message) {
        return false;
    }

    let parsed: Value = match serde_json::from_str(&message.encryption) {
        Ok(value) => value,
        Err(_) => return false,
    };
    is_supported_encryption_envelope(&parsed)
}

fn external_email_thread_targets(references: &[Value]) -> Vec<String> {
    references
        .iter()
        .filter(|reference| {
            reference.get("type").and_then(Value::as_str) == Some("external_email")
                && reference
                    .get("metadata")
                    .and_then(|metadata| metadata.get("relation"))
                    .and_then(Value::as_str)
                    != Some("message_id")
        })
        .filter_map(|reference| reference.get("target").and_then(Value::as_str))
        .map(str::trim)
        .filter(|target| !target.is_empty())
        .map(str::to_string)
        .collect()
}

fn apply_external_email_thread_match(
    message: &mut AFPMessage,
    thread_match: Option<(String, String)>,
) {
    let Some((thread_id, parent_id)) = thread_match else {
        return;
    };

    if message.thread_id.trim().is_empty() {
        message.thread_id = thread_id;
    } else {
        message.thread_id = thread_id;
    }

    if message.parent_id.is_none() {
        message.parent_id = Some(parent_id);
    }
}

