#[derive(serde::Deserialize)]
struct LlmConfigRequest {
    backend: String,
    #[serde(default)]
    provider: Option<String>,
    #[serde(default)]
    model: Option<String>,
    #[serde(default)]
    api_key: Option<String>,
    #[serde(default)]
    ollama_url: Option<String>,
}

fn llm_config_change_requires_recent_session(body: &LlmConfigRequest) -> bool {
    body.api_key
        .as_deref()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty())
        || matches!(body.backend.as_str(), "byok" | "runpod")
        || body
            .ollama_url
            .as_deref()
            .map(str::trim)
            .is_some_and(|value| !value.is_empty())
}

// -- LLM config ----------------------------------------------------------------

async fn llm_config_get_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let mut config = state
        .db
        .get_llm_config(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                "no LLM config; call POST /agent/provision first".to_string(),
            )
        })?;
    let inference_ready = llm_resolution::resolve_user_inference_backend(&state.db, &user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .is_some();
    if let Some(object) = config.as_object_mut() {
        object.insert("inference_ready".to_string(), Value::Bool(inference_ready));
    }
    Ok(Json(config))
}

fn contains_explicit_trial_time(content: &str) -> bool {
    let lowered = content.to_ascii_lowercase();
    ["am", "pm", ":00", ":15", ":30", ":45", "noon", "midnight"]
        .iter().any(|marker| lowered.contains(marker))
}

async fn llm_config_set_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<LlmConfigRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let (user, session) = authenticated_user_and_session(&state.db, &headers).await?;
    if llm_config_change_requires_recent_session(&body) {
        require_recent_high_risk_session(&session)?;
    }
    let (backend, monthly_budget) = match body.backend.as_str() {
        "hosted" => {
            let billing = state
                .db
                .get_billing_status(&user.id)
                .await
                .unwrap_or_default();
            if billing
                .get("plan")
                .and_then(|p| p.as_str())
                .unwrap_or("free")
                != "pro"
            {
                return Err((
                    StatusCode::PAYMENT_REQUIRED,
                    "hosted LLM requires pro plan ($9/mo)".to_string(),
                ));
            }
            (LlmBackend::Hosted, 900i32)
        }
        "byok" => (LlmBackend::Byok, 0i32),
        "ollama" => (LlmBackend::Ollama, 0i32),
        "runpod" => (LlmBackend::RunPod, 0i32),
        other => return Err((StatusCode::BAD_REQUEST, format!("unknown backend: {other}"))),
    };
    let provider = body.provider.unwrap_or_else(|| "anthropic".to_string());
    let default_model = match backend {
        LlmBackend::RunPod => "Qwen/Qwen3.5-35B-A3B".to_string(),
        LlmBackend::Ollama => "llama3.2".to_string(),
        LlmBackend::Byok => llm_resolution::default_model_for_provider(&provider).to_string(),
        LlmBackend::Hosted => "claude-haiku-4-5-20251001".to_string(),
    };
    let cfg = LlmConfig {
        id: Ulid::new().to_string(),
        owner_user_id: user.id.clone(),
        backend,
        provider: provider.clone(),
        model: body
            .model
            .filter(|value| !value.trim().is_empty())
            .unwrap_or(default_model),
        encrypted_api_key: body.api_key,
        ollama_url: body.ollama_url,
        monthly_budget_cents: monthly_budget,
        usage_cents_current_month: 0,
    };
    state
        .db
        .upsert_llm_config(&cfg)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(llm_config_save_response(&cfg)))
}

fn llm_backend_label(backend: &LlmBackend) -> &'static str {
    match backend {
        LlmBackend::Hosted => "hosted",
        LlmBackend::Byok => "byok",
        LlmBackend::Ollama => "ollama",
        LlmBackend::RunPod => "runpod",
    }
}

fn llm_config_save_response(cfg: &LlmConfig) -> Value {
    serde_json::json!({
        "updated": true,
        "backend": llm_backend_label(&cfg.backend),
        "provider": cfg.provider,
        "model": cfg.model,
        "monthly_budget_cents": cfg.monthly_budget_cents,
        "usage_cents_current_month": cfg.usage_cents_current_month,
    })
}

fn llm_ping_reason_from_body(body: &str) -> String {
    let trimmed = body.trim();
    if trimmed.is_empty() {
        return "provider returned an empty error response".to_string();
    }
    if let Ok(parsed) = serde_json::from_str::<Value>(trimmed) {
        if let Some(message) = parsed
            .get("error")
            .and_then(|error| {
                error
                    .get("message")
                    .and_then(Value::as_str)
                    .or_else(|| error.as_str())
            })
            .or_else(|| parsed.get("message").and_then(Value::as_str))
            .or_else(|| parsed.get("detail").and_then(Value::as_str))
        {
            return message.trim().to_string();
        }
    }
    let compact = trimmed.split_whitespace().collect::<Vec<_>>().join(" ");
    if compact.len() > 180 {
        format!("{}…", &compact[..180])
    } else {
        compact
    }
}

fn llm_ping_failure_reason(provider: &str, status: StatusCode) -> String {
    format!("{provider} returned HTTP {}. Check logs.", status.as_u16())
}

// -- LLM ping — verify connection without triggering inference -----------------

async fn llm_config_ping_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let cfg = state
        .db
        .get_llm_config(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "no LLM config saved yet".to_string()))?;

    let backend_label = cfg
        .get("backend")
        .and_then(Value::as_str)
        .unwrap_or("byok");
    let provider = cfg
        .get("provider")
        .and_then(Value::as_str)
        .unwrap_or("anthropic");
    let Some(resolved) = llm_resolution::resolve_user_inference_backend(&state.db, &user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
    else {
        return Ok(Json(serde_json::json!({
            "ok": false,
            "backend": backend_label,
            "provider": provider,
            "reason": "The saved model settings are incomplete. Check the key, endpoint, and account access.",
        })));
    };
    let request = crate::inference::InferenceRequest {
        system: "This is a connection check. Follow the user instruction exactly.".to_string(),
        messages: vec![crate::inference::InferenceMessage {
            role: "user".to_string(),
            content: "Reply with only OK.".to_string(),
        }],
        max_tokens: 8,
        temperature: 0.0,
    };
    match tokio::time::timeout(
        std::time::Duration::from_secs(15),
        crate::inference::dispatch_infer(&resolved.backend, &resolved.model, &request),
    )
    .await
    {
        Ok(Ok(response)) if !response.content.trim().is_empty() => Ok(Json(serde_json::json!({
            "ok": true,
            "backend": backend_label,
            "provider": provider,
            "model": resolved.model,
        }))),
        Ok(Ok(_)) => Ok(Json(serde_json::json!({
            "ok": false,
            "backend": backend_label,
            "provider": provider,
            "reason": "The model connected but returned no text.",
        }))),
        Ok(Err(error)) => {
            tracing::warn!(%error, backend = backend_label, provider, "LLM connection inference failed");
            Ok(Json(serde_json::json!({
                "ok": false,
                "backend": backend_label,
                "provider": provider,
                "reason": "The model could not complete a small test request. Check the saved key, model name, and provider access.",
            })))
        }
        Err(_) => Ok(Json(serde_json::json!({
            "ok": false,
            "backend": backend_label,
            "provider": provider,
            "reason": "The model connection test timed out.",
        }))),
    }
}

// -- /ui/decision — record user decision for a generative card decision_point -

async fn ui_decision_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<UiDecisionRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    // Store as an AFP user_decision message in the thread so the running agent
    // can pick it up via its relay WebSocket subscription.
    let decision_msg = AFPMessage {
        protocol: "afp-v1".to_string(),
        id: Ulid::new().to_string(),
        thread_id: body.thread_id.clone(),
        parent_id: None,
        from: user.id.clone(),
        to: body.agent_id.clone().map(|a| vec![a]).unwrap_or_default(),
        timestamp: chrono::Utc::now().to_rfc3339(),
        r#type: "user_decision".to_string(),
        kind: None,
        supertags: vec![],
        subtype: Some("decision_point".to_string()),
        content: serde_json::json!({
            "card_id":            body.card_id,
            "decision_point_id":  body.decision_point_id,
            "selected_option_id": body.selected_option_id,
            "decided_by":         user.id,
        }),
        metadata: Some(serde_json::json!({
            "origin": "workspace_ui_decision"
        })),
        views: vec![],
        references: vec![],
        typed_refs: vec![],
        attachments: vec![],
        encryption: None,
        signature: String::new(),
        store_in_relational: true,
        prev_hash: None,
    };

    let decision_message_id = decision_msg.id.clone();
    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        decision_msg,
    )
    .await
    .map_err(status_to_http)?;

    let active_persona = state
        .db
        .get_active_agent_persona(&user.id)
        .await
        .ok()
        .flatten();
    if body.decision_point_id == "approval_gate" || body.decision_point_id == "clarification_gate" {
        let thread_messages =
            thread_messages_for_headers(&state.db, &headers, &body.thread_id).await?;
        let app_messages = thread_messages
            .into_iter()
            .map(proto_to_app)
            .collect::<Vec<_>>();
        if let Some(card_message) = app_messages.iter().find(|message| {
            message.r#type == "generative_card"
                && message.content.get("card_id").and_then(Value::as_str)
                    == Some(body.card_id.as_str())
        }) {
            let objective = card_message
                .content
                .get("query")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();

            let is_approval_confirm = body.selected_option_id == "confirm_orchestration";
            let clarification_instruction =
                clarification_option_instruction(&body.selected_option_id);
            let is_clarification_proceed = body.decision_point_id == "clarification_gate"
                && clarification_instruction.is_some();

            if (is_approval_confirm || is_clarification_proceed) && !objective.is_empty() {
                let resolved_llm = llm_resolution::resolve_user_inference_backend(
                    &state.db,
                    &user.id,
                )
                .await
                .map_err(internal_error)
                .map_err(status_to_http)?
                .ok_or_else(|| {
                    (
                        StatusCode::BAD_REQUEST,
                        "no usable LLM backend is configured".to_string(),
                    )
                })?;
                let model = resolved_llm.model;
                let backend = resolved_llm.backend;
                let master_instance = state
                    .db
                    .get_master_agent_instance(&user.id)
                    .await
                    .map_err(internal_error)
                    .map_err(status_to_http)?
                    .ok_or_else(|| (StatusCode::NOT_FOUND, "no master agent".to_string()))?;
                let lora_active = master_instance["lora_genome_active"]
                    .as_bool()
                    .unwrap_or(false);
                let agent_id = master_instance["agent_id"].as_str().map(str::to_string);
                let orchestration_objective = if body.decision_point_id == "clarification_gate" {
                    apply_clarification_context(&objective, &body.selected_option_id)
                } else {
                    objective.clone()
                };

                if let Some(agent_id_value) = agent_id.clone() {
                    if body.decision_point_id == "clarification_gate"
                        || body.decision_point_id == "approval_gate"
                    {
                        let (title, text, tone) = if body.decision_point_id == "clarification_gate"
                        {
                            clarification_option_summary(&body.selected_option_id)
                        } else {
                            approval_option_summary(&body.selected_option_id)
                        };
                        let text = decision_user_facing_text(text, active_persona.as_ref());
                        let section_id = if body.decision_point_id == "clarification_gate" {
                            "clarification_gate"
                        } else {
                            "approval_gate"
                        };
                        let assumption_update = serde_json::json!({
                            "card_id": body.card_id,
                            "section": {
                                "id": section_id,
                                "type": "callout",
                                "order": 3,
                                "status": "complete",
                                "content": {
                                    "title": title,
                                    "text": text,
                                    "tone": tone,
                                }
                            }
                        });
                        if let Ok(msg) = new_server_message(
                            agent_id_value.clone(),
                            vec![],
                            body.thread_id.clone(),
                            "card_section_update",
                            assumption_update,
                            vec![],
                            vec![],
                            vec![],
                            true,
                        ) {
                            let _ = store_private_app_message(
                                &state.db,
                                &state.metrics,
                                &state.relay_tx,
                                &user.id,
                                msg,
                            )
                            .await;
                        }
                    }

                    let update = serde_json::json!({
                        "card_id": body.card_id,
                        "section": {
                            "id": "progress",
                            "type": "progress",
                            "order": 1,
                            "status": "streaming",
                            "content": {
                                "text": decision_user_facing_text(if body.decision_point_id == "clarification_gate" {
                                    clarification_option_progress_text(&body.selected_option_id)
                                } else {
                                    "Approval received. Starting orchestration now."
                                }, active_persona.as_ref()),
                                "pct": 25
                            }
                        }
                    });
                    if let Ok(msg) = new_server_message(
                        agent_id_value,
                        vec![],
                        body.thread_id.clone(),
                        "card_section_update",
                        update,
                        vec![],
                        vec![],
                        vec![],
                        true,
                    ) {
                        let _ = store_private_app_message(
                            &state.db,
                            &state.metrics,
                            &state.relay_tx,
                            &user.id,
                            msg,
                        )
                        .await;
                    }
                }

                spawn_orchestration_run(
                    state.clone(),
                    user.id.clone(),
                    backend,
                    model,
                    orchestration_objective,
                    crate::response_queue_policy::AgentExecutionProfile::from_mode("balanced"),
                    lora_active,
                    body.thread_id.clone(),
                    body.card_id.clone(),
                    agent_id,
                    None,
                );
            } else if body.selected_option_id == "cancel_orchestration"
                || body.selected_option_id == "cancel_for_clarification"
            {
                let master_instance = state
                    .db
                    .get_master_agent_instance(&user.id)
                    .await
                    .map_err(internal_error)
                    .map_err(status_to_http)?
                    .ok_or_else(|| (StatusCode::NOT_FOUND, "no master agent".to_string()))?;
                if let Some(agent_id) = master_instance["agent_id"].as_str() {
                    if body.decision_point_id == "approval_gate" {
                        let (title, text, tone) = approval_option_summary(&body.selected_option_id);
                        let text = decision_user_facing_text(text, active_persona.as_ref());
                        let approval_update = serde_json::json!({
                            "card_id": body.card_id,
                            "section": {
                                "id": "approval_gate",
                                "type": "callout",
                                "order": 3,
                                "status": "complete",
                                "content": {
                                    "title": title,
                                    "text": text,
                                    "tone": tone,
                                }
                            }
                        });
                        if let Ok(msg) = new_server_message(
                            agent_id.to_string(),
                            vec![],
                            body.thread_id.clone(),
                            "card_section_update",
                            approval_update,
                            vec![],
                            vec![],
                            vec![],
                            true,
                        ) {
                            let _ = store_private_app_message(
                                &state.db,
                                &state.metrics,
                                &state.relay_tx,
                                &user.id,
                                msg,
                            )
                            .await;
                        }
                    }

                    let update = serde_json::json!({
                        "card_id": body.card_id,
                        "section": {
                            "id": "final",
                            "type": "final_answer",
                            "order": 4,
                            "status": "complete",
                            "content": {
                                "text": decision_user_facing_text(if body.decision_point_id == "clarification_gate" {
                                    "Orchestration cancelled until a more specific objective is provided."
                                } else {
                                    "Orchestration cancelled before any external action was started."
                                }, active_persona.as_ref())
                            }
                        }
                    });
                    if let Ok(msg) = new_server_message(
                        agent_id.to_string(),
                        vec![],
                        body.thread_id.clone(),
                        "card_section_update",
                        update,
                        vec![],
                        vec![],
                        vec![],
                        true,
                    ) {
                        let _ = store_private_app_message(
                            &state.db,
                            &state.metrics,
                            &state.relay_tx,
                            &user.id,
                            msg,
                        )
                        .await;
                    }
                }
            }
        }
    }

    Ok(Json(serde_json::json!({
        "success":    true,
        "message_id": decision_message_id,
    })))
}

// -- /user/agent-preferences — get/set agent optimization preferences ----------

async fn agent_preferences_get_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<AgentPreferences>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    let prefs = state
        .db
        .get_agent_preferences(&user.id)
        .await
        .ok()
        .flatten()
        .and_then(|v| serde_json::from_value::<AgentPreferences>(v).ok())
        .unwrap_or_default();

    Ok(Json(prefs))
}

async fn agent_preferences_set_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<AgentPreferences>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    let valid_modes = ["speed", "cost", "balanced"];
    if !valid_modes.contains(&body.optimization_mode.as_str()) {
        return Err((
            StatusCode::BAD_REQUEST,
            format!(
                "optimization_mode must be one of: {}",
                valid_modes.join(", ")
            ),
        ));
    }

    state
        .db
        .upsert_agent_preferences(
            &user.id,
            &body.optimization_mode,
            body.auto_confirm_threshold_cents,
            body.show_cost_estimates,
            body.default_store_in_history,
            &serde_json::json!({}),
            &serde_json::json!({}),
        )
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({"updated": true})))
}

async fn daemons_list_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let daemons = daemon_registry::get_active_daemons(&state.db, &user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let warnings = daemon_registry::daemon_health_check(&state.db, Some(&user.id))
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let stale_map = warnings
        .into_iter()
        .map(|warning| (warning.daemon_id, warning.stale_minutes))
        .collect::<HashMap<_, _>>();
    let items = daemons
        .into_iter()
        .map(|daemon| {
            serde_json::json!({
                "daemon_id": daemon.daemon_id,
                "daemon_kind": format!("{:?}", daemon.daemon_kind).to_lowercase(),
                "display_name": daemon.daemon_kind.display_name(),
                "status": format!("{:?}", daemon.status).to_lowercase(),
                "workflow_id": daemon.workflow_id,
                "delegated_key_id": daemon.delegated_key_id,
                "last_heartbeat_at": daemon.last_heartbeat_at,
                "created_at": daemon.created_at,
                "revoked_at": daemon.revoked_at,
                "policy_config": daemon.policy_config,
                "stale_minutes": stale_map.get(&daemon.daemon_id).copied(),
            })
        })
        .collect::<Vec<_>>();
    Ok(Json(serde_json::json!({ "daemons": items })))
}

async fn daemon_heartbeat_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(daemon_id): Path<String>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let registration = daemon_registry::get_daemon_registration(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "daemon not found".to_string()))?;
    if registration.user_id != user.id {
        return Err((
            StatusCode::FORBIDDEN,
            "daemon not owned by this user".to_string(),
        ));
    }
    let heartbeat = daemon_registry::get_latest_heartbeat(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({
        "daemon": registration,
        "heartbeat": heartbeat,
    })))
}

async fn daemon_revoke_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(daemon_id): Path<String>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let registration = daemon_registry::get_daemon_registration(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "daemon not found".to_string()))?;
    if registration.user_id != user.id {
        return Err((
            StatusCode::FORBIDDEN,
            "daemon not owned by this user".to_string(),
        ));
    }
    daemon_registry::revoke_daemon(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({
        "updated": true,
        "daemon_id": daemon_id,
        "status": "revoked",
    })))
}

// -- Knowledge Curator — backlinks & supertags ---------------------------------

/// `GET /notes/backlinks/{message_id}`
///
/// Returns all backlink edges (both inbound and outbound) for the given AFP
/// message id.  Uses the `afp_backlinks` derived index — never scans raw
/// `backlink_update` history.
async fn note_backlinks_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(message_id): Path<String>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let backlinks = state
        .db
        .list_backlinks_for_message(&user.id, &message_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let items: Vec<Value> = backlinks
        .into_iter()
        .map(|record| {
            serde_json::json!({
                "backlink_id": record.backlink_id,
                "source_id":   record.source_id,
                "target_id":   record.target_id,
                "direction":   if record.source_id == message_id { "outbound" } else { "inbound" },
                "link_kind":   format!("{:?}", record.link_kind).to_lowercase(),
                "similarity":  record.similarity,
                "entities":    record.entities,
                "created_at":  record.created_at,
            })
        })
        .collect();
    let count = items.len();
    Ok(Json(serde_json::json!({
        "message_id": message_id,
        "backlinks":  items,
        "count":      count,
    })))
}

/// `GET /notes/supertags`
///
/// Returns the top-20 supertags most frequently used in the authenticated
/// user's knowledge cards, ordered by frequency descending.  Used to populate
/// the DashboardFeed filter strip and the NoteView autocomplete palette.
async fn user_supertags_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let tags = state
        .db
        .list_top_supertags(&user.id, 20)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({ "supertags": tags })))
}

/// `POST /notes/{message_id}/backlink-override`
///
/// Stores a `backlink_override` AFP message that the Knowledge Curator will
/// respect on the next processing pass for this message.
///
/// Body: `{ "suppress": bool, "rules": "...", "scope": "message" | "thread" }`
async fn note_backlink_override_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(message_id): Path<String>,
    Json(body): Json<Value>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let suppress = body
        .get("suppress")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let rules = body
        .get("rules")
        .and_then(Value::as_str)
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let scope_str = body
        .get("scope")
        .and_then(Value::as_str)
        .unwrap_or("message");
    let thread_id = body
        .get("thread_id")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();

    let content = serde_json::json!({
        "source_id":  message_id,
        "thread_id":  if thread_id.is_empty() { Value::Null } else { Value::String(thread_id.clone()) },
        "scope":      scope_str,
        "suppress":   suppress,
        "rules":      rules,
    });

    let msg = crate::afp::Message {
        protocol: "afp-v1".to_string(),
        id: format!("backlink-override.{}", Ulid::new()),
        thread_id: if thread_id.is_empty() {
            format!("thread.backlink-override.{message_id}")
        } else {
            thread_id
        },
        parent_id: String::new(),
        from: format!("omnyid://user/{}", user.id),
        to: vec!["omnyid://workspace/user".to_string()],
        timestamp: chrono::Utc::now().to_rfc3339(),
        r#type: crate::message::AFP_TYPE_BACKLINK_OVERRIDE.to_string(),
        kind: None,
        supertags: vec![],
        content: content.to_string(),
        signature: String::new(),
        encryption: "{}".to_string(),
        views: "[]".to_string(),
        references: serde_json::json!([message_id]).to_string(),
        attachments: "[]".to_string(),
        store_in_relational: false,
        subtype: scope_str.to_string(),
        metadata: serde_json::json!({ "source_id": message_id }).to_string(),
    };
    state
        .db
        .store_private_message(&user.id, &msg, content)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "stored": true,
        "message_id": message_id,
        "suppress": suppress,
        "scope": scope_str,
    })))
}

// -- Multi-hop backlink graph ---------------------------------------------------

/// `GET /backlinks/graph?root={id}&depth={n}`
///
/// BFS traversal of the backlink graph starting from `root`, up to `depth`
/// hops (max 4).  Returns all reachable nodes and edges as a JSON graph
/// suitable for force-directed visualisation.
async fn backlinks_graph_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(params): Query<std::collections::HashMap<String, String>>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let root = params
        .get("root")
        .filter(|s| !s.is_empty())
        .ok_or_else(|| {
            (
                StatusCode::BAD_REQUEST,
                "root query parameter required".to_string(),
            )
        })?
        .clone();
    let depth: u32 = params
        .get("depth")
        .and_then(|s| s.parse().ok())
        .unwrap_or(2)
        .min(4);

    let (nodes, edges) = state
        .db
        .bfs_backlinks_graph(&user.id, &root, depth)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    let edge_values: Vec<Value> = edges
        .into_iter()
        .map(|record| {
            serde_json::json!({
                "backlink_id": record.backlink_id,
                "source_id":   record.source_id,
                "target_id":   record.target_id,
                "link_kind":   format!("{:?}", record.link_kind).to_lowercase(),
                "similarity":  record.similarity,
                "entities":    record.entities,
                "created_at":  record.created_at,
            })
        })
        .collect();
    let node_count = nodes.len();
    let edge_count = edge_values.len();

    Ok(Json(serde_json::json!({
        "root":   root,
        "depth":  depth,
        "nodes":  nodes,
        "edges":  edge_values,
        "node_count": node_count,
        "edge_count": edge_count,
    })))
}

