// -- Federation inbound handler -------------------------------------------------

#[derive(serde::Deserialize)]
struct FederationSendRequest {
    recipient_agent_id: String,
    thread_id: String,
    body: String,
    #[serde(default)]
    subject: Option<String>,
}

const FEDERATION_SUBJECT_MAX_CHARS: usize = 200;
const FEDERATION_BODY_MAX_CHARS: usize = 8_000;
fn validate_federation_send_fields(
    recipient_agent_id: &str,
    thread_id: &str,
    body: &str,
    subject: Option<&str>,
) -> Result<(), (StatusCode, String)> {
    if crate::federation::parse_agent_id(recipient_agent_id).is_none() {
        return Err((
            StatusCode::BAD_REQUEST,
            "recipient_agent_id must look like agent:name@example.com".to_string(),
        ));
    }
    if body.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            "message body is required".to_string(),
        ));
    }
    if body.chars().count() > FEDERATION_BODY_MAX_CHARS {
        return Err((
            StatusCode::PAYLOAD_TOO_LARGE,
            format!("message body must be {FEDERATION_BODY_MAX_CHARS} characters or fewer"),
        ));
    }
    if let Some(subject) = subject {
        if subject.chars().count() > FEDERATION_SUBJECT_MAX_CHARS {
            return Err((
                StatusCode::PAYLOAD_TOO_LARGE,
                format!("subject must be {FEDERATION_SUBJECT_MAX_CHARS} characters or fewer"),
            ));
        }
    }
    if thread_id.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            "thread_id is required for federated delivery".to_string(),
        ));
    }
    Ok(())
}

/// POST /federation/send
///
/// Authenticated UI endpoint for sending a signed AFP message to a peer agent on
/// another homeserver. Stores the outbound message locally, then relays it using
/// `.well-known/afp-delegation` discovery.
async fn federation_send_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(req): Json<FederationSendRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    enforce_rate_limit(
        &state,
        authenticated_rate_limit_key("federation_send", &headers),
        RateLimitPolicy {
            max_requests: 20,
            window: Duration::from_secs(60),
        },
    )
    .await?;
    let user = authenticated_user(&state.db, &headers).await?;

    let recipient_agent_id = req.recipient_agent_id.trim();
    let body = req.body.trim();
    let thread_id = req.thread_id.trim();
    let subject = req
        .subject
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    validate_federation_send_fields(recipient_agent_id, thread_id, body, subject)?;

    let local_card = AgentCard::from_env();
    let Some((_, own_domain)) = crate::federation::parse_agent_id(&local_card.agent_id) else {
        return Err((
            StatusCode::PRECONDITION_FAILED,
            "OMNYID_AGENT_ID must be a valid agent id before federation can send".to_string(),
        ));
    };
    let signing_key = env_hex_32("OMNYID_SIGNING_KEY_HEX")
        .map_err(|err| (StatusCode::PRECONDITION_FAILED, err))?
        .ok_or_else(|| {
            (
                StatusCode::PRECONDITION_FAILED,
                "OMNYID_SIGNING_KEY_HEX is required for signed federation send".to_string(),
            )
        })?;

    let mut message = build_federated_agent_message(
        &local_card.agent_id,
        recipient_agent_id,
        thread_id,
        subject.unwrap_or("Agent to agent message"),
        body,
        &user.id,
    );
    sign_message(&mut message, &signing_key);

    let message_id = message.id.clone();
    let delivery_thread_id = message.thread_id.clone();
    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        message.clone(),
    )
    .await
    .map_err(status_to_http)?;

    dispatch_federated_message_with_receipt(
        &state,
        &user.id,
        &message,
        recipient_agent_id,
        own_domain,
        &signing_key,
    )
    .await?;

    Ok(Json(serde_json::json!({
        "success": true,
        "message_id": message_id,
        "thread_id": delivery_thread_id,
        "source_thread_id": if delivery_thread_id == thread_id { Value::Null } else { Value::String(thread_id.to_string()) },
        "recipient_agent_id": recipient_agent_id,
    })))
}

// GAP-110: in-process nonce store for federation replay protection.
// Nonces are ULIDs (time-prefixed); entries older than 5 minutes are pruned on access.
fn federation_seen_nonces()
-> &'static std::sync::Mutex<std::collections::HashMap<String, std::time::Instant>> {
    static NONCES: std::sync::OnceLock<
        std::sync::Mutex<std::collections::HashMap<String, std::time::Instant>>,
    > = std::sync::OnceLock::new();
    NONCES.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// POST /federation/relay
///
/// Accepts an AFP message relayed from another Omnyid homeserver.
/// Verifies the Ed25519 signature using the sender's `.well-known/afp-delegation`.
async fn federation_relay_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    body: axum::body::Bytes,
) -> Result<Json<Value>, (StatusCode, String)> {
    let body_str = std::str::from_utf8(&body)
        .map_err(|_| (StatusCode::BAD_REQUEST, "body must be UTF-8".to_string()))?;

    let sender_domain = headers
        .get("X-Omnyid-Sender")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("")
        .to_string();
    if sender_domain.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            "X-Omnyid-Sender header required".to_string(),
        ));
    }

    let signature = headers
        .get("X-Omnyid-Signature")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("")
        .to_string();
    if signature.is_empty() {
        return Err((
            StatusCode::UNAUTHORIZED,
            "X-Omnyid-Signature header required".to_string(),
        ));
    }

    let relay_req = crate::federation::verify_inbound_relay(body_str, &sender_domain, &signature)
        .await
        .map_err(|e| (StatusCode::UNAUTHORIZED, e.to_string()))?;

    // GAP-110: reject replayed requests by tracking seen nonces for 5 minutes.
    {
        let nonce_ttl = std::time::Duration::from_secs(300);
        let mut seen = federation_seen_nonces()
            .lock()
            .unwrap_or_else(|p| p.into_inner());
        let now = std::time::Instant::now();
        seen.retain(|_, ts| now.duration_since(*ts) < nonce_ttl);
        if seen.contains_key(&relay_req.nonce) {
            return Err((
                StatusCode::CONFLICT,
                "duplicate nonce — replay rejected".to_string(),
            ));
        }
        seen.insert(relay_req.nonce.clone(), now);
    }

    // Ingest the relayed message into the local AFP database
    tracing::info!(
        "federation: accepted relay from {} nonce={}",
        sender_domain,
        relay_req.nonce
    );
    let proto = relay_message_to_proto(relay_req.message).map_err(status_to_http)?;
    validate_federated_proto_sender(&proto, &sender_domain).map_err(status_to_http)?;
    let ack = store_proto_message(&state.db, &state.metrics, &state.relay_tx, proto)
        .await
        .map_err(status_to_http)?
        .into_inner();

    Ok(Json(serde_json::json!({
        "accepted": ack.success,
        "message_id": ack.message_id,
        "nonce": relay_req.nonce,
        "sender": sender_domain,
    })))
}

fn relay_message_to_proto(message: Value) -> Result<Message, Status> {
    if let Some(proto) = relay_message_json_to_proto(&message) {
        return Ok(proto);
    }

    if let Ok(app_message) = serde_json::from_value::<AFPMessage>(message) {
        return Ok(app_to_proto(app_message));
    }

    Err(Status::invalid_argument(
        "relay payload must contain a valid AFP message",
    ))
}

fn validate_federated_proto_sender(message: &Message, sender_domain: &str) -> Result<(), Status> {
    let Some((_, message_domain)) = crate::federation::parse_agent_id(&message.from) else {
        return Err(Status::invalid_argument(
            "relay payload must use a valid AFP sender agent id",
        ));
    };
    if message_domain != sender_domain.trim() {
        return Err(Status::unauthenticated(
            "relay payload sender domain does not match verified federation sender",
        ));
    }
    Ok(())
}

fn relay_message_json_to_proto(message: &Value) -> Option<Message> {
    let object = message.as_object()?;
    let content = object.get("content")?.as_str()?;

    Some(Message {
        protocol: object
            .get("protocol")
            .and_then(Value::as_str)
            .unwrap_or("afp-v1")
            .to_string(),
        id: object.get("id").and_then(Value::as_str)?.to_string(),
        thread_id: object.get("thread_id").and_then(Value::as_str)?.to_string(),
        parent_id: object
            .get("parent_id")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        from: object.get("from").and_then(Value::as_str)?.to_string(),
        to: object
            .get("to")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default(),
        timestamp: object
            .get("timestamp")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        r#type: object.get("type").and_then(Value::as_str)?.to_string(),
        kind: object
            .get("kind")
            .and_then(Value::as_str)
            .map(str::to_string),
        content: content.to_string(),
        signature: object
            .get("signature")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        encryption: object
            .get("encryption")
            .and_then(Value::as_str)
            .unwrap_or("{}")
            .to_string(),
        views: object
            .get("views")
            .and_then(Value::as_str)
            .unwrap_or("[]")
            .to_string(),
        references: object
            .get("references")
            .and_then(Value::as_str)
            .unwrap_or("[]")
            .to_string(),
        attachments: object
            .get("attachments")
            .and_then(Value::as_str)
            .unwrap_or("[]")
            .to_string(),
        store_in_relational: object
            .get("store_in_relational")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        subtype: object
            .get("subtype")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        metadata: object
            .get("metadata")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        supertags: object
            .get("supertags")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default(),
    })
}

// -- Master Agent Orchestration Handlers --------------------------------------

/// SHA-256 fingerprint of remote IP + User-Agent for anon session tracking.
pub(super) fn anon_fingerprint(headers: &HeaderMap) -> String {
    use std::fmt::Write;
    // Use request_ip_identity — only trusts X-Forwarded-For when OMNYID_BEHIND_TRUSTED_PROXY=true.
    let ip = request_ip_identity(headers);
    let ua = headers
        .get("user-agent")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("unknown");
    let input = format!("{ip}{ua}");
    let hash_bytes = crate::post_quantum::hkdf_sha256(input.as_bytes(), b"", b"fp", 16);
    let mut hex = String::with_capacity(32);
    for b in hash_bytes {
        let _ = write!(hex, "{b:02x}");
    }
    hex
}

/// GET /dashboard/session
/// For unauthenticated users: checks the 3-session limit and provisions an
/// ephemeral master agent. Authenticated users skip the gate entirely.
async fn dashboard_session_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    // Authenticated users bypass the anon gate
    if authenticated_user(&state.db, &headers).await.is_ok() {
        return Ok(Json(
            serde_json::json!({"authenticated": true, "session": "persistent"}),
        ));
    }

    let fingerprint = anonymous_session_identity_key(&headers);
    let count = state
        .db
        .check_and_increment_anon_session(&fingerprint)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    if count > 3 {
        return Err((
            StatusCode::FORBIDDEN,
            "You've used all 3 free guest sessions from this device. Sign in to continue."
                .to_string(),
        ));
    }

    let domain = std::env::var("OMNYID_DOMAIN").unwrap_or_else(|_| "omnyid.com".to_string());
    let instance = crate::agent_template::AgentInstance::provision_ephemeral(&fingerprint, &domain);
    let instance_id = instance.id.clone();
    state
        .db
        .save_master_agent_instance(&instance)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "authenticated": false,
        "session": "ephemeral",
        "session_count": count,
        "sessions_remaining": 3 - count,
        "agent_instance_id": instance_id,
    })))
}

/// POST /agent/onboarding
/// Saves soul.md answers and regenerates soul_md for the user's master agent.
#[derive(serde::Deserialize)]
struct OnboardingAnswers {
    personality: String,
    tone: String,
    goals: String,
    rules: String,
}

async fn agent_onboarding_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<OnboardingAnswers>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let instance = state
        .db
        .get_master_agent_instance(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                "no master agent instance found".to_string(),
            )
        })?;
    let instance_id = instance["id"].as_str().unwrap_or("").to_string();

    let soul_md = format!(
        "# Agent Soul — {display_name}\n\
        \n\
        ## Personality\n\
        {personality}\n\
        \n\
        ## Tone\n\
        {tone}\n\
        \n\
        ## Goals\n\
        {goals}\n\
        \n\
        ## Rules\n\
        {rules}\n\
        \n\
        ## LoRA Status\n\
        LoRA fine-tuning will progressively internalise this profile.\n\
        Once confidence reaches 85 %, this file will be archived.\n",
        display_name = user.display_name,
        personality = body.personality,
        tone = body.tone,
        goals = body.goals,
        rules = body.rules,
    );

    state
        .db
        .update_agent_soul(&user.id, &instance_id, &soul_md)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    Ok(Json(
        serde_json::json!({"updated": true, "soul_md": soul_md}),
    ))
}

