// -- Cron trigger scheduler ----------------------------------------------------

/// Converts a single day-of-week token from unix numbering (0=Sun, 1=Mon, ...,
/// 6=Sat) to Quartz numbering (1=Sun, 2=Mon, ..., 7=Sat) by incrementing
/// numeric values.  The special value `7` (alternate Sun in unix) maps to `1`.
fn unix_dow_token_to_quartz(token: &str) -> String {
    // Pass through non-numeric atoms unchanged (e.g. "MON", "SUN").
    if let Ok(n) = token.parse::<u32>() {
        let q = match n {
            7 => 1,     // unix 7 = Sun ? Quartz 1
            d => d + 1, // unix 0-6 ? Quartz 1-7
        };
        return q.to_string();
    }
    token.to_string()
}

/// Converts a day-of-week field from unix notation to Quartz notation.
/// Handles `*`, single values, ranges (`1-5`), lists (`1,3,5`), and steps
/// (`*/2`, `1-5/2`).  Numeric values are incremented per `unix_dow_token_to_quartz`.
fn unix_dow_field_to_quartz(field: &str) -> String {
    if field == "*" || field == "?" {
        return field.to_string();
    }
    // Handle step expressions: e.g. "1-5/2" or "*/2"
    if let Some((range_part, step)) = field.split_once('/') {
        let converted_range = unix_dow_field_to_quartz(range_part);
        return format!("{converted_range}/{step}");
    }
    // Handle list: "1,3,5"
    if field.contains(',') {
        return field
            .split(',')
            .map(|t| unix_dow_token_to_quartz(t.trim()))
            .collect::<Vec<_>>()
            .join(",");
    }
    // Handle range: "1-5"
    if let Some((lo, hi)) = field.split_once('-') {
        return format!(
            "{}-{}",
            unix_dow_token_to_quartz(lo.trim()),
            unix_dow_token_to_quartz(hi.trim())
        );
    }
    unix_dow_token_to_quartz(field)
}

/// Converts a standard 5-field unix cron expression (`min hour dom month dow`)
/// into the 7-field Quartz format (`sec min hour dom month dow year`) expected
/// by the `cron` crate.
///
/// Day-of-week numbering is also converted: unix 0=Sun,1=Mon…6=Sat ?
/// Quartz 1=Sun,2=Mon…7=Sat.  Passes 7-field expressions through unchanged.
fn cron_to_quartz(expr: &str) -> String {
    let fields: Vec<&str> = expr.split_whitespace().collect();
    match fields.len() {
        5 => {
            // unix 5-field: min hour dom month dow
            let dow_quartz = unix_dow_field_to_quartz(fields[4]);
            format!(
                "0 {} {} {} {} {} *",
                fields[0], fields[1], fields[2], fields[3], dow_quartz
            )
        }
        6 => {
            // Assume sec min hour dom month dow (dow already in Quartz, just add year)
            format!("{expr} *")
        }
        _ => expr.to_string(),
    }
}

/// Computes the next UTC fire time for a cron expression **after** `from`.
/// Returns `None` if the expression is unparseable or has no upcoming fires.
fn cron_next_fire_at(
    five_field_expr: &str,
    from: chrono::DateTime<chrono::Utc>,
) -> Option<chrono::DateTime<chrono::Utc>> {
    use cron::Schedule;
    use std::str::FromStr;
    let quartz = cron_to_quartz(five_field_expr);
    let schedule = Schedule::from_str(&quartz).ok()?;
    schedule.after(&from).next()
}

// -- Email trigger dispatcher --------------------------------------------------

/// Fire a single email-family workflow run.
///
/// Mirrors `fire_scheduled_workflow_run` but uses `trigger_kind = "email"` and
/// embeds the email subject/from in the trigger observation's `payload_summary`.
async fn fire_email_trigger_workflow_run(
    state: &Arc<AppState>,
    reg: &crate::db::WorkflowTriggerRegistrationRecord,
    activation_id: &str,
    now_utc: chrono::DateTime<chrono::Utc>,
    email_subject: Option<&str>,
    email_from: Option<&str>,
) -> Result<String, String> {
    let user_id = &reg.owner_user_id;
    let workflow_id = &reg.workflow_id;
    let deployment_id = &reg.deployment_id;
    let trigger_node_id = &reg.trigger_node_id;
    let now_str = now_utc.to_rfc3339();

    let deployment = state
        .db
        .get_workflow_deployment(user_id, workflow_id, deployment_id)
        .await
        .map_err(|e| format!("load deployment {deployment_id}: {e}"))?;
    let graph_snapshot = deployment["graph_snapshot"].clone();
    let ir_snapshot = deployment["ir_snapshot"].clone();
    let environment = graph_snapshot
        .get("environment")
        .and_then(serde_json::Value::as_str)
        .or_else(|| {
            ir_snapshot
                .get("environment")
                .and_then(serde_json::Value::as_str)
        });
    let trigger_kind = "email";
    let enriched_ir =
        enrich_workflow_ir_for_run(&ir_snapshot, deployment_id, environment, trigger_kind, None);

    workflow_trigger_policy_check(reg, trigger_kind).map_err(|e| format!("policy_check: {e}"))?;

    let nonce = trigger_replay_nonce(deployment_id, trigger_node_id, activation_id);
    let claimed = state
        .db
        .check_and_claim_replay_nonce(user_id, &nonce)
        .await
        .map_err(|e| format!("replay nonce claim: {e}"))?;
    if !claimed {
        return Err(format!(
            "duplicate email activation: activation_id={activation_id} already processed"
        ));
    }

    let mut run = workflow_run_record(
        workflow_id,
        deployment_id,
        user_id,
        trigger_kind,
        None,
        None,
        &graph_snapshot,
        &enriched_ir,
    );
    apply_workflow_skill_capsule_runtime_effects(&mut run, &enriched_ir).await;
    enrich_workflow_run_with_private_calendar_context(&state.db, &mut run).await;
    enrich_workflow_run_with_private_finance_context(&state.db, &mut run).await;
    state
        .db
        .append_workflow_run(&run)
        .await
        .map_err(|e| format!("append run: {e}"))?;

    let obs = crate::db::TriggerObservabilityRecord {
        observation_id: format!("wftobs_{}", ulid::Ulid::new().to_string().to_lowercase()),
        registration_id: reg.registration_id.clone(),
        workflow_id: workflow_id.clone(),
        deployment_id: deployment_id.clone(),
        owner_user_id: user_id.clone(),
        trigger_source: "email".to_string(),
        trigger_time: now_str.clone(),
        payload_summary: serde_json::json!({
            "trigger_kind": "email",
            "email_subject": email_subject,
            "email_from": email_from,
        }),
        schedule_metadata: serde_json::json!({}),
        delayed_resumption_reason: None,
        hybrid_decision_chain: serde_json::json!([]),
        run_initiation_trace: serde_json::json!({
            "run_id": run.run_id,
            "workflow_id": workflow_id,
            "deployment_id": deployment_id,
            "trigger_node_id": trigger_node_id,
            "activation_id": activation_id,
            "via": "email_trigger_dispatcher",
        }),
        replay_nonce: nonce,
        created_at: now_str.clone(),
    };
    if let Err(e) = state.db.write_trigger_observation(&obs).await {
        tracing::warn!(
            run_id = %run.run_id,
            workflow_id = %workflow_id,
            error = %e,
            "email_dispatcher: failed to write trigger observation; run continues"
        );
    }

    let wait_resume_records = workflow_wait_resume_records_for_run(
        workflow_id,
        deployment_id,
        user_id,
        &run,
        &enriched_ir,
    );
    for record in &wait_resume_records {
        if let Err(e) = state.db.append_workflow_wait_resume_record(record).await {
            tracing::warn!(
                run_id = %run.run_id,
                error = %e,
                "email_dispatcher: failed to write wait-resume record; run continues"
            );
        }
    }

    tracing::info!(
        run_id = %run.run_id,
        workflow_id = %workflow_id,
        registration_id = %reg.registration_id,
        email_subject = ?email_subject,
        "email_dispatcher: fired email trigger workflow run"
    );
    Ok(run.run_id)
}

/// One tick of the email trigger dispatcher.
///
/// Reads up to 50 unprocessed entries from `public.email_trigger_queue`,
/// then for each entry fires a workflow run for every user who has a
/// registered `email`-family trigger registration. After all users are
/// processed the queue entry is marked dispatched.
async fn email_trigger_dispatcher_tick(state: Arc<AppState>) {
    let events = match state.db.list_pending_email_trigger_events(50).await {
        Ok(evts) => evts,
        Err(e) => {
            tracing::error!(
                error = %e,
                "email_dispatcher_tick: list_pending_email_trigger_events failed"
            );
            return;
        }
    };

    if events.is_empty() {
        return;
    }

    let user_ids = match state.db.list_user_ids().await {
        Ok(ids) => ids,
        Err(e) => {
            tracing::error!(error = %e, "email_dispatcher_tick: list_user_ids failed");
            return;
        }
    };

    let now_utc = chrono::Utc::now();

    for (event_id, _provider, _account, email_subject, email_from, _message_uid) in &events {
        for user_id in &user_ids {
            let registrations = match state
                .db
                .list_due_email_trigger_registrations_for_user(user_id)
                .await
            {
                Ok(regs) => regs,
                Err(e) => {
                    tracing::warn!(
                        user_id = %user_id,
                        error = %e,
                        "email_dispatcher_tick: list_due_email_trigger_registrations failed; skipping user"
                    );
                    continue;
                }
            };

            for reg in registrations {
                let activation_id = format!("{}:{}", event_id, reg.registration_id);
                if let Err(e) = fire_email_trigger_workflow_run(
                    &state,
                    &reg,
                    &activation_id,
                    now_utc,
                    email_subject.as_deref(),
                    email_from.as_deref(),
                )
                .await
                {
                    tracing::warn!(
                        user_id = %user_id,
                        registration_id = %reg.registration_id,
                        event_id = %event_id,
                        error = %e,
                        "email_dispatcher_tick: fire_email_trigger_workflow_run failed"
                    );
                }
            }
        }

        if let Err(e) = state.db.mark_email_trigger_dispatched(event_id).await {
            tracing::warn!(
                event_id = %event_id,
                error = %e,
                "email_dispatcher_tick: mark_email_trigger_dispatched failed"
            );
        }
    }
}

pub(in crate::server) async fn enrich_workflow_run_with_private_finance_context(
    db: &Db,
    run: &mut WorkflowRunRecord,
) {
    let Some(result_obj) = run.result_json.as_object_mut() else {
        return;
    };
    let Some(contract) = workflow_result_contract_from_result(result_obj) else {
        return;
    };
    let Some(contract_obj) = contract.as_object() else {
        return;
    };
    let workflow = contract_obj
        .get("workflow")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if workflow != "finance_guardian" {
        return;
    }

    let account_count_row = match sqlx::query(
        "SELECT COUNT(*) AS account_count
         FROM finance_accounts
         WHERE user_id = $1 AND enabled = true",
    )
    .bind(&run.owner_user_id)
    .fetch_one(&db.pool)
    .await
    {
        Ok(row) => row,
        Err(err) => {
            tracing::warn!(
                run_id = %run.run_id,
                workflow = workflow,
                owner_user_id = %run.owner_user_id,
                error = %err,
                "workflow run finance-context enrichment failed to load account count"
            );
            return;
        }
    };
    let account_count = account_count_row
        .try_get::<i64, _>("account_count")
        .unwrap_or(0);

    let recent_period_days = 30_i64;
    let recent_totals_row = match sqlx::query(
        "SELECT
             COUNT(*) AS recent_transaction_count,
             COALESCE(SUM(CASE WHEN amount_cents < 0 THEN ABS(amount_cents) ELSE 0 END), 0) AS recent_expense_cents,
             COALESCE(SUM(CASE WHEN amount_cents > 0 THEN amount_cents ELSE 0 END), 0) AS recent_income_cents
         FROM finance_transactions
         WHERE user_id = $1
           AND txn_date >= CURRENT_DATE - INTERVAL '30 days'",
    )
    .bind(&run.owner_user_id)
    .fetch_one(&db.pool)
    .await
    {
        Ok(row) => row,
        Err(err) => {
            tracing::warn!(
                run_id = %run.run_id,
                workflow = workflow,
                owner_user_id = %run.owner_user_id,
                error = %err,
                "workflow run finance-context enrichment failed to load recent totals"
            );
            return;
        }
    };
    let recent_transaction_count = recent_totals_row
        .try_get::<i64, _>("recent_transaction_count")
        .unwrap_or(0);
    let recent_expense_cents = recent_totals_row
        .try_get::<i64, _>("recent_expense_cents")
        .unwrap_or(0);
    let recent_income_cents = recent_totals_row
        .try_get::<i64, _>("recent_income_cents")
        .unwrap_or(0);

    let top_category_rows = match sqlx::query(
        "SELECT category, SUM(ABS(amount_cents)) AS total_cents, COUNT(*) AS txn_count
         FROM finance_transactions
         WHERE user_id = $1
           AND amount_cents < 0
           AND txn_date >= CURRENT_DATE - INTERVAL '90 days'
         GROUP BY category
         ORDER BY total_cents DESC
         LIMIT 3",
    )
    .bind(&run.owner_user_id)
    .fetch_all(&db.pool)
    .await
    {
        Ok(rows) => rows,
        Err(err) => {
            tracing::warn!(
                run_id = %run.run_id,
                workflow = workflow,
                owner_user_id = %run.owner_user_id,
                error = %err,
                "workflow run finance-context enrichment failed to load category totals"
            );
            return;
        }
    };
    let top_spend_categories = top_category_rows
        .iter()
        .map(|row| {
            serde_json::json!({
                "category": row
                    .try_get::<Option<String>, _>("category")
                    .ok()
                    .flatten()
                    .unwrap_or_else(|| "other".to_string()),
                "total_cents": row.try_get::<i64, _>("total_cents").unwrap_or(0),
                "txn_count": row.try_get::<i64, _>("txn_count").unwrap_or(0),
            })
        })
        .collect::<Vec<_>>();
    let top_spend_category = top_spend_categories
        .first()
        .and_then(Value::as_object)
        .and_then(|value| value.get("category"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let top_spend_total_cents = top_spend_categories
        .first()
        .and_then(Value::as_object)
        .and_then(|value| value.get("total_cents"))
        .and_then(Value::as_i64);

    let anomaly_rows = match sqlx::query(
        "SELECT txn_id, txn_date::text AS txn_date, amount_cents, currency, description,
                merchant_name, category, anomaly_reason
         FROM finance_transactions
         WHERE user_id = $1 AND is_anomaly = true
         ORDER BY txn_date DESC
         LIMIT 5",
    )
    .bind(&run.owner_user_id)
    .fetch_all(&db.pool)
    .await
    {
        Ok(rows) => rows,
        Err(err) => {
            tracing::warn!(
                run_id = %run.run_id,
                workflow = workflow,
                owner_user_id = %run.owner_user_id,
                error = %err,
                "workflow run finance-context enrichment failed to load anomalies"
            );
            return;
        }
    };
    let recent_anomalies = anomaly_rows
        .iter()
        .map(|row| {
            serde_json::json!({
                "txn_id": row.try_get::<String, _>("txn_id").unwrap_or_default(),
                "txn_date": row.try_get::<String, _>("txn_date").unwrap_or_default(),
                "amount_cents": row.try_get::<i64, _>("amount_cents").unwrap_or(0),
                "currency": row.try_get::<String, _>("currency").unwrap_or_else(|_| "AUD".to_string()),
                "description": row.try_get::<String, _>("description").unwrap_or_default(),
                "merchant_name": row.try_get::<Option<String>, _>("merchant_name").ok().flatten(),
                "category": row.try_get::<Option<String>, _>("category").ok().flatten(),
                "anomaly_reason": row.try_get::<Option<String>, _>("anomaly_reason").ok().flatten(),
            })
        })
        .collect::<Vec<_>>();

    let monthly_rows = match sqlx::query(
        "SELECT DATE_TRUNC('month', txn_date)::date::text AS month,
                SUM(CASE WHEN amount_cents < 0 THEN ABS(amount_cents) ELSE 0 END) AS expenses_cents,
                SUM(CASE WHEN amount_cents > 0 THEN amount_cents ELSE 0 END) AS income_cents
         FROM finance_transactions
         WHERE user_id = $1
           AND txn_date >= CURRENT_DATE - INTERVAL '3 months'
         GROUP BY month
         ORDER BY month DESC",
    )
    .bind(&run.owner_user_id)
    .fetch_all(&db.pool)
    .await
    {
        Ok(rows) => rows,
        Err(err) => {
            tracing::warn!(
                run_id = %run.run_id,
                workflow = workflow,
                owner_user_id = %run.owner_user_id,
                error = %err,
                "workflow run finance-context enrichment failed to load monthly totals"
            );
            return;
        }
    };
    let monthly_totals = monthly_rows
        .iter()
        .map(|row| {
            serde_json::json!({
                "month": row.try_get::<String, _>("month").unwrap_or_default(),
                "expenses_cents": row.try_get::<i64, _>("expenses_cents").unwrap_or(0),
                "income_cents": row.try_get::<i64, _>("income_cents").unwrap_or(0),
            })
        })
        .collect::<Vec<_>>();

    result_obj.insert(
        "finance_input_context".to_string(),
        serde_json::json!({
            "account_count": account_count,
            "recent_period_days": recent_period_days,
            "recent_transaction_count": recent_transaction_count,
            "recent_expense_cents": recent_expense_cents,
            "recent_income_cents": recent_income_cents,
            "top_spend_category": top_spend_category,
            "top_spend_total_cents": top_spend_total_cents,
            "top_spend_categories": top_spend_categories,
            "recent_anomalies": recent_anomalies.clone(),
            "monthly_totals": monthly_totals,
        }),
    );

    if let Some(finance_digest) = result_obj
        .get_mut("finance_digest")
        .and_then(Value::as_object_mut)
    {
        finance_digest.insert(
            "account_count".to_string(),
            serde_json::json!(account_count),
        );
        finance_digest.insert(
            "recent_period_days".to_string(),
            serde_json::json!(recent_period_days),
        );
        finance_digest.insert(
            "recent_transaction_count".to_string(),
            serde_json::json!(recent_transaction_count),
        );
        finance_digest.insert(
            "recent_expense_cents".to_string(),
            serde_json::json!(recent_expense_cents),
        );
        finance_digest.insert(
            "recent_income_cents".to_string(),
            serde_json::json!(recent_income_cents),
        );
        finance_digest.insert(
            "anomaly_count".to_string(),
            serde_json::json!(recent_anomalies.len()),
        );
        finance_digest.insert(
            "top_spend_category".to_string(),
            top_spend_category
                .clone()
                .map(Value::String)
                .unwrap_or(Value::Null),
        );
        finance_digest.insert(
            "top_spend_total_cents".to_string(),
            top_spend_total_cents
                .map(|value| serde_json::json!(value))
                .unwrap_or(Value::Null),
        );
    }

    let context_note = if recent_transaction_count == 0 {
        format!(
            "Private finance context: no transactions were recorded in the last {} days.",
            recent_period_days
        )
    } else {
        format!(
            "Private finance context: {} transactions across {} active accounts in the last {} days with {} cents of expenses and {} cents of income.",
            recent_transaction_count,
            account_count,
            recent_period_days,
            recent_expense_cents,
            recent_income_cents
        )
    };
    let notes = result_obj
        .entry("anomaly_notes".to_string())
        .or_insert_with(|| Value::Array(Vec::new()));
    if let Some(notes_array) = notes.as_array_mut() {
        push_unique_result_string(notes_array, context_note);
        if let (Some(category), Some(total_cents)) =
            (top_spend_category.as_deref(), top_spend_total_cents)
        {
            push_unique_result_string(
                notes_array,
                format!(
                    "Top spend category over the last 90 days: {} at {} cents.",
                    category, total_cents
                ),
            );
        }
        if recent_anomalies.is_empty() {
            push_unique_result_string(
                notes_array,
                "No flagged spending anomalies were found in the current finance window.",
            );
        } else if let Some(anomaly) = recent_anomalies.first().and_then(Value::as_object) {
            let description = anomaly
                .get("description")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .unwrap_or("recent transaction");
            let reason = anomaly
                .get("anomaly_reason")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .unwrap_or("unusual spending pattern");
            push_unique_result_string(
                notes_array,
                format!("Most recent anomaly: {} ({})", description, reason),
            );
        }
    }
}

/// Long-running background task: runs the email trigger dispatcher every 60 seconds.
/// 45-second initial delay (staggers relative to cron scheduler's 30s delay).
async fn email_trigger_dispatcher_loop(state: Arc<AppState>) {
    tracing::info!("email_trigger_dispatcher: starting (60s interval)");
    tokio::time::sleep(tokio::time::Duration::from_secs(45)).await;
    loop {
        email_trigger_dispatcher_tick(state.clone()).await;
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}
// -- File-drop / watcher adapter -----------------------------------------------

/// Fire one workflow run for a `file_drop`-kind trigger registration.
///
/// Mirrors `fire_email_trigger_workflow_run` but embeds file metadata in the
/// trigger observation payload summary.
async fn fire_file_drop_trigger_workflow_run(
    state: &Arc<AppState>,
    reg: &crate::db::WorkflowTriggerRegistrationRecord,
    activation_id: &str,
    now_utc: chrono::DateTime<chrono::Utc>,
    watched_path: &str,
    file_name: &str,
    file_size_bytes: Option<i64>,
    file_event_type: &str,
) -> Result<String, String> {
    let user_id = &reg.owner_user_id;
    let workflow_id = &reg.workflow_id;
    let deployment_id = &reg.deployment_id;
    let trigger_node_id = &reg.trigger_node_id;
    let now_str = now_utc.to_rfc3339();

    // 1. Load deployment snapshot.
    let deployment = state
        .db
        .get_workflow_deployment(user_id, workflow_id, deployment_id)
        .await
        .map_err(|e| format!("load deployment {deployment_id}: {e}"))?;
    let graph_snapshot = deployment["graph_snapshot"].clone();
    let ir_snapshot = deployment["ir_snapshot"].clone();
    let environment = graph_snapshot
        .get("environment")
        .and_then(serde_json::Value::as_str)
        .or_else(|| {
            ir_snapshot
                .get("environment")
                .and_then(serde_json::Value::as_str)
        });
    let trigger_kind = "file_drop";
    let enriched_ir =
        enrich_workflow_ir_for_run(&ir_snapshot, deployment_id, environment, trigger_kind, None);

    // 2. Policy check — must pass before replay nonce is claimed.
    workflow_trigger_policy_check(reg, trigger_kind).map_err(|e| format!("policy_check: {e}"))?;

    // 3. Replay nonce — prevents double-firing if dispatcher runs overlap.
    let nonce = trigger_replay_nonce(deployment_id, trigger_node_id, activation_id);
    let claimed = state
        .db
        .check_and_claim_replay_nonce(user_id, &nonce)
        .await
        .map_err(|e| format!("replay nonce claim: {e}"))?;
    if !claimed {
        return Err(format!(
            "duplicate file_drop activation: activation_id={activation_id} already processed"
        ));
    }

    // 4. Persist run record.
    let mut run = workflow_run_record(
        workflow_id,
        deployment_id,
        user_id,
        trigger_kind,
        None,
        None,
        &graph_snapshot,
        &enriched_ir,
    );
    apply_workflow_skill_capsule_runtime_effects(&mut run, &enriched_ir).await;
    enrich_workflow_run_with_private_calendar_context(&state.db, &mut run).await;
    enrich_workflow_run_with_private_finance_context(&state.db, &mut run).await;
    state
        .db
        .append_workflow_run(&run)
        .await
        .map_err(|e| format!("append run: {e}"))?;

    // 4. Trigger observation.
    let obs = crate::db::TriggerObservabilityRecord {
        observation_id: format!("wftobs_{}", ulid::Ulid::new().to_string().to_lowercase()),
        registration_id: reg.registration_id.clone(),
        workflow_id: workflow_id.clone(),
        deployment_id: deployment_id.clone(),
        owner_user_id: user_id.clone(),
        trigger_source: "file_drop".to_string(),
        trigger_time: now_str.clone(),
        payload_summary: serde_json::json!({
            "trigger_kind": "file_drop",
            "watched_path": watched_path,
            "file_name": file_name,
            "file_size_bytes": file_size_bytes,
            "file_event_type": file_event_type,
        }),
        schedule_metadata: serde_json::json!({}),
        delayed_resumption_reason: None,
        hybrid_decision_chain: serde_json::json!([]),
        run_initiation_trace: serde_json::json!({
            "run_id": run.run_id,
            "workflow_id": workflow_id,
            "deployment_id": deployment_id,
            "trigger_node_id": trigger_node_id,
            "activation_id": activation_id,
            "via": "file_drop_trigger_dispatcher",
        }),
        replay_nonce: nonce,
        created_at: now_str.clone(),
    };
    if let Err(e) = state.db.write_trigger_observation(&obs).await {
        tracing::warn!(
            run_id = %run.run_id,
            workflow_id = %workflow_id,
            error = %e,
            "file_drop_dispatcher: failed to write trigger observation; run continues"
        );
    }

    // 5. Wait-resume records.
    let wait_resume_records = workflow_wait_resume_records_for_run(
        workflow_id,
        deployment_id,
        user_id,
        &run,
        &enriched_ir,
    );
    for record in &wait_resume_records {
        if let Err(e) = state.db.append_workflow_wait_resume_record(record).await {
            tracing::warn!(
                run_id = %run.run_id,
                error = %e,
                "file_drop_dispatcher: failed to write wait-resume record; run continues"
            );
        }
    }

    tracing::info!(
        run_id = %run.run_id,
        workflow_id = %workflow_id,
        registration_id = %reg.registration_id,
        file_name = %file_name,
        "file_drop_dispatcher: fired file_drop trigger workflow run"
    );
    Ok(run.run_id)
}

/// One tick of the file-drop trigger dispatcher.
///
/// Reads up to 50 pending file-drop events, then for each event fires a run
/// for every user who has a registered `file_drop`-kind trigger registration.
async fn file_drop_trigger_dispatcher_tick(state: Arc<AppState>) {
    let events = match state.db.list_pending_file_drop_trigger_events(50).await {
        Ok(evts) => evts,
        Err(e) => {
            tracing::error!(error = %e, "file_drop_dispatcher_tick: list_pending_file_drop_trigger_events failed");
            return;
        }
    };

    if events.is_empty() {
        return;
    }

    let user_ids = match state.db.list_user_ids().await {
        Ok(ids) => ids,
        Err(e) => {
            tracing::error!(error = %e, "file_drop_dispatcher_tick: list_user_ids failed");
            return;
        }
    };

    let now_utc = chrono::Utc::now();

    for (event_id, watched_path, file_name, file_size_bytes, file_event_type) in &events {
        for user_id in &user_ids {
            let registrations = match state
                .db
                .list_due_file_drop_trigger_registrations_for_user(user_id)
                .await
            {
                Ok(regs) => regs,
                Err(e) => {
                    tracing::warn!(
                        user_id = %user_id,
                        error = %e,
                        "file_drop_dispatcher_tick: list_due_file_drop_trigger_registrations failed; skipping user"
                    );
                    continue;
                }
            };

            for reg in registrations {
                let activation_id = format!("{}:{}", event_id, reg.registration_id);
                if let Err(e) = fire_file_drop_trigger_workflow_run(
                    &state,
                    &reg,
                    &activation_id,
                    now_utc,
                    watched_path,
                    file_name,
                    *file_size_bytes,
                    file_event_type,
                )
                .await
                {
                    tracing::warn!(
                        user_id = %user_id,
                        registration_id = %reg.registration_id,
                        event_id = %event_id,
                        error = %e,
                        "file_drop_dispatcher_tick: fire_file_drop_trigger_workflow_run failed"
                    );
                }
            }
        }

        if let Err(e) = state.db.mark_file_drop_trigger_dispatched(event_id).await {
            tracing::warn!(
                event_id = %event_id,
                error = %e,
                "file_drop_dispatcher_tick: mark_file_drop_trigger_dispatched failed"
            );
        }
    }
}

/// One tick of the file-drop watcher.
///
/// Reads `OMNYID_FILE_WATCH_DIR` from env; if unset, is a no-op.  Lists all
/// files in the directory and enqueues any whose mtime is within the last
/// `window_secs` seconds (default 70 — slightly wider than the 60s poll
/// cadence to avoid missing files at tick boundaries).
async fn file_drop_watcher_tick(state: Arc<AppState>) {
    let watch_dir = match std::env::var("OMNYID_FILE_WATCH_DIR") {
        Ok(d) if !d.is_empty() => d,
        _ => return, // no watched directory configured
    };
    let window_secs = std::env::var("OMNYID_FILE_WATCH_WINDOW_SECS")
        .ok()
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(70);

    let entries = match std::fs::read_dir(&watch_dir) {
        Ok(e) => e,
        Err(err) => {
            tracing::warn!(path = %watch_dir, error = %err, "file_drop_watcher: read_dir failed");
            return;
        }
    };

    let cutoff = std::time::SystemTime::now()
        .checked_sub(std::time::Duration::from_secs(window_secs))
        .unwrap_or(std::time::UNIX_EPOCH);

    for entry_result in entries {
        let entry = match entry_result {
            Ok(e) => e,
            Err(_) => continue,
        };
        let metadata = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };
        if !metadata.is_file() {
            continue;
        }
        let mtime = metadata.modified().unwrap_or(std::time::UNIX_EPOCH);
        if mtime < cutoff {
            continue;
        }

        let file_name = entry.file_name().to_string_lossy().to_string();
        let file_size = metadata.len() as i64;
        let event_id = format!("fdrop_{}", ulid::Ulid::new().to_string().to_lowercase());

        if let Err(err) = state
            .db
            .enqueue_file_drop_trigger_event(
                &event_id,
                &watch_dir,
                &file_name,
                Some(file_size),
                "created",
            )
            .await
        {
            tracing::warn!(
                event_id = %event_id,
                file_name = %file_name,
                error = %err,
                "file_drop_watcher: enqueue_file_drop_trigger_event failed; continuing"
            );
        }
    }
}

/// Long-running background task: polls the watched directory every 60 seconds
/// then runs the dispatcher tick.  60-second initial delay.
async fn file_drop_watcher_loop(state: Arc<AppState>) {
    if std::env::var("OMNYID_FILE_WATCH_DIR")
        .map(|d| d.is_empty())
        .unwrap_or(true)
    {
        tracing::info!("file_drop_watcher: OMNYID_FILE_WATCH_DIR not set; watcher disabled");
        return;
    }
    tracing::info!("file_drop_watcher: starting (60s interval)");
    tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    loop {
        file_drop_watcher_tick(state.clone()).await;
        file_drop_trigger_dispatcher_tick(state.clone()).await;
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

// -- Internal workflow runtime event dispatcher --------------------------------

/// Fire one workflow run for an `internal_event`-kind trigger registration.
///
/// Respects optional `source_workflow_id` filter in the registration descriptor:
/// if the registration's descriptor_json contains `"source_workflow_id"`, only
/// events from that workflow are dispatched to it.
async fn fire_internal_event_trigger_workflow_run(
    state: &Arc<AppState>,
    reg: &crate::db::WorkflowTriggerRegistrationRecord,
    activation_id: &str,
    now_utc: chrono::DateTime<chrono::Utc>,
    event_type: &str,
    source_workflow_id: Option<&str>,
    source_run_id: Option<&str>,
    payload: &serde_json::Value,
) -> Result<String, String> {
    // Optional source_workflow_id filter: skip if registration restricts to a
    // different source workflow.
    if let Some(required_src) = reg
        .descriptor_json
        .get("source_workflow_id")
        .and_then(|v| v.as_str())
    {
        if source_workflow_id != Some(required_src) {
            return Err(format!(
                "internal_event filter mismatch: registration requires source_workflow_id={required_src}"
            ));
        }
    }

    let user_id = &reg.owner_user_id;
    let workflow_id = &reg.workflow_id;
    let deployment_id = &reg.deployment_id;
    let trigger_node_id = &reg.trigger_node_id;
    let now_str = now_utc.to_rfc3339();

    let deployment = state
        .db
        .get_workflow_deployment(user_id, workflow_id, deployment_id)
        .await
        .map_err(|e| format!("load deployment {deployment_id}: {e}"))?;
    let graph_snapshot = deployment["graph_snapshot"].clone();
    let ir_snapshot = deployment["ir_snapshot"].clone();
    let environment = graph_snapshot
        .get("environment")
        .and_then(serde_json::Value::as_str)
        .or_else(|| {
            ir_snapshot
                .get("environment")
                .and_then(serde_json::Value::as_str)
        });
    let trigger_kind = "internal_event";
    let enriched_ir =
        enrich_workflow_ir_for_run(&ir_snapshot, deployment_id, environment, trigger_kind, None);

    // Policy check — must pass before replay nonce is claimed.
    workflow_trigger_policy_check(reg, trigger_kind).map_err(|e| format!("policy_check: {e}"))?;

    let nonce = trigger_replay_nonce(deployment_id, trigger_node_id, activation_id);
    let claimed = state
        .db
        .check_and_claim_replay_nonce(user_id, &nonce)
        .await
        .map_err(|e| format!("replay nonce claim: {e}"))?;
    if !claimed {
        return Err(format!(
            "duplicate internal_event activation: activation_id={activation_id} already processed"
        ));
    }

    let mut run = workflow_run_record(
        workflow_id,
        deployment_id,
        user_id,
        trigger_kind,
        None,
        None,
        &graph_snapshot,
        &enriched_ir,
    );
    apply_workflow_skill_capsule_runtime_effects(&mut run, &enriched_ir).await;
    enrich_workflow_run_with_private_calendar_context(&state.db, &mut run).await;
    enrich_workflow_run_with_private_finance_context(&state.db, &mut run).await;
    state
        .db
        .append_workflow_run(&run)
        .await
        .map_err(|e| format!("append run: {e}"))?;

    let obs = crate::db::TriggerObservabilityRecord {
        observation_id: format!("wftobs_{}", ulid::Ulid::new().to_string().to_lowercase()),
        registration_id: reg.registration_id.clone(),
        workflow_id: workflow_id.clone(),
        deployment_id: deployment_id.clone(),
        owner_user_id: user_id.clone(),
        trigger_source: "internal_event".to_string(),
        trigger_time: now_str.clone(),
        payload_summary: internal_event_trigger_payload_summary(
            event_type,
            source_workflow_id,
            source_run_id,
            payload,
        ),
        schedule_metadata: serde_json::json!({}),
        delayed_resumption_reason: None,
        hybrid_decision_chain: serde_json::json!([]),
        run_initiation_trace: serde_json::json!({
            "run_id": run.run_id,
            "workflow_id": workflow_id,
            "deployment_id": deployment_id,
            "trigger_node_id": trigger_node_id,
            "activation_id": activation_id,
            "via": "internal_event_dispatcher",
        }),
        replay_nonce: nonce,
        created_at: now_str.clone(),
    };
    if let Err(e) = state.db.write_trigger_observation(&obs).await {
        tracing::warn!(
            run_id = %run.run_id,
            error = %e,
            "internal_event_dispatcher: failed to write trigger observation; run continues"
        );
    }

    let wait_resume_records = workflow_wait_resume_records_for_run(
        workflow_id,
        deployment_id,
        user_id,
        &run,
        &enriched_ir,
    );
    for record in &wait_resume_records {
        if let Err(e) = state.db.append_workflow_wait_resume_record(record).await {
            tracing::warn!(
                run_id = %run.run_id,
                error = %e,
                "internal_event_dispatcher: failed to write wait-resume record; run continues"
            );
        }
    }

    tracing::info!(
        run_id = %run.run_id,
        workflow_id = %workflow_id,
        registration_id = %reg.registration_id,
        event_type = %event_type,
        "internal_event_dispatcher: fired internal_event trigger workflow run"
    );
    Ok(run.run_id)
}

/// One tick of the internal event dispatcher.
///
/// Reads up to 50 pending internal events from `public.internal_event_queue`.
/// For each event, fires runs only for trigger registrations belonging to the
/// same user who owns the source workflow (internal events are tenant-scoped).
async fn internal_event_dispatcher_tick(state: Arc<AppState>) {
    let events = match state.db.list_pending_internal_events(50).await {
        Ok(evts) => evts,
        Err(e) => {
            tracing::error!(error = %e, "internal_event_dispatcher_tick: list_pending_internal_events failed");
            return;
        }
    };

    if events.is_empty() {
        return;
    }

    let now_utc = chrono::Utc::now();

    for (event_id, event_type, source_workflow_id, source_run_id, owner_user_id, payload) in &events
    {
        // Internal events are dispatched only within the owning tenant.
        let registrations = match state
            .db
            .list_due_internal_event_trigger_registrations_for_user(owner_user_id)
            .await
        {
            Ok(regs) => regs,
            Err(e) => {
                tracing::warn!(
                    owner_user_id = %owner_user_id,
                    error = %e,
                    "internal_event_dispatcher_tick: list_due_internal_event_trigger_registrations failed; skipping"
                );
                if let Err(e2) = state.db.mark_internal_event_dispatched(event_id).await {
                    tracing::warn!(event_id = %event_id, error = %e2, "internal_event_dispatcher_tick: mark_dispatched failed");
                }
                continue;
            }
        };

        for reg in registrations {
            let activation_id = format!("{}:{}", event_id, reg.registration_id);
            if let Err(e) = fire_internal_event_trigger_workflow_run(
                &state,
                &reg,
                &activation_id,
                now_utc,
                event_type,
                source_workflow_id.as_deref(),
                source_run_id.as_deref(),
                payload,
            )
            .await
            {
                tracing::warn!(
                    owner_user_id = %owner_user_id,
                    registration_id = %reg.registration_id,
                    event_id = %event_id,
                    error = %e,
                    "internal_event_dispatcher_tick: fire_internal_event_trigger_workflow_run failed"
                );
            }
        }

        if let Err(e) = state.db.mark_internal_event_dispatched(event_id).await {
            tracing::warn!(
                event_id = %event_id,
                error = %e,
                "internal_event_dispatcher_tick: mark_internal_event_dispatched failed"
            );
        }
    }
}

/// Long-running background task: runs the internal event dispatcher every 60 seconds.
/// 90-second initial delay (staggers from cron=30s, email=45s, file_drop=60s).
async fn internal_event_dispatcher_loop(state: Arc<AppState>) {
    tracing::info!("internal_event_dispatcher: starting (60s interval)");
    tokio::time::sleep(tokio::time::Duration::from_secs(90)).await;
    loop {
        internal_event_dispatcher_tick(state.clone()).await;
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

/// Enqueue an internal workflow runtime event non-fatally.
///
/// Called by `workflow_run_start_http` when a run reaches a terminal state
/// (completed / failed / simulated) so downstream workflows with
/// `trigger_kind=internal_event` can chain off it.
fn enqueue_internal_workflow_event_nonblocking(
    state: Arc<AppState>,
    event_type: &str,
    source_workflow_id: &str,
    source_run_id: &str,
    owner_user_id: &str,
    payload: serde_json::Value,
) {
    let event_id = format!("ievt_{}", ulid::Ulid::new().to_string().to_lowercase());
    let event_type = event_type.to_string();
    let source_workflow_id = source_workflow_id.to_string();
    let source_run_id = source_run_id.to_string();
    let owner_user_id = owner_user_id.to_string();
    tokio::spawn(async move {
        if let Err(e) = state
            .db
            .enqueue_internal_event(
                &event_id,
                &event_type,
                Some(&source_workflow_id),
                Some(&source_run_id),
                &owner_user_id,
                &payload,
            )
            .await
        {
            tracing::warn!(
                event_id = %event_id,
                error = %e,
                "enqueue_internal_workflow_event: failed; downstream triggers will not fire"
            );
        }
    });
}

// -- POST /ingest/internal/{event_type} — authenticated internal event ingress --

#[derive(serde::Deserialize)]
struct InternalIngestBody {
    source_workflow_id: Option<String>,
    source_run_id: Option<String>,
    #[serde(default)]
    payload: serde_json::Value,
}

/// `POST /ingest/internal/{event_type}`
///
/// Authenticated endpoint allowing any component of the system (or an
/// authorised caller) to emit an internal runtime event.  The event is
/// enqueued in `public.internal_event_queue` and will be dispatched to all
/// matching `internal_event`-kind trigger registrations owned by the calling
/// user on the next dispatcher tick.
fn workflow_internal_event_payload(
    workflow_id: &str,
    run: &WorkflowRunRecord,
    trigger_kind: &str,
) -> Value {
    let mut payload = serde_json::json!({
        "workflow_id": workflow_id,
        "run_id": run.run_id,
        "status": run.status,
        "trigger_kind": trigger_kind,
    });
    if let Some(result) = run.result_json.as_object() {
        if let Some(outcome_kind) = result
            .get("skill_capsule_outcome_kind")
            .and_then(Value::as_str)
        {
            payload["skill_capsule_outcome_kind"] = Value::String(outcome_kind.to_string());
        }
        if let Some(receipt_status) = result
            .get("skill_capsule_receipt_status")
            .and_then(Value::as_str)
        {
            payload["skill_capsule_receipt_status"] = Value::String(receipt_status.to_string());
        }
        if let Some(blocked_reason) = result.get("blocked_reason").and_then(Value::as_str) {
            payload["blocked_reason"] = Value::String(blocked_reason.to_string());
        }
        if let Some(failed_reason) = result.get("failed_reason").and_then(Value::as_str) {
            payload["failed_reason"] = Value::String(failed_reason.to_string());
        }
    }
    payload
}

fn internal_event_trigger_payload_summary(
    event_type: &str,
    source_workflow_id: Option<&str>,
    source_run_id: Option<&str>,
    payload: &Value,
) -> Value {
    let mut summary = serde_json::json!({
        "trigger_kind": "internal_event",
        "event_type": event_type,
        "source_workflow_id": source_workflow_id,
        "source_run_id": source_run_id,
        "payload": payload,
    });
    if let Some(payload_obj) = payload.as_object() {
        if let Some(outcome_kind) = payload_obj
            .get("skill_capsule_outcome_kind")
            .and_then(Value::as_str)
        {
            summary["skill_capsule_outcome_kind"] = Value::String(outcome_kind.to_string());
        }
        if let Some(receipt_status) = payload_obj
            .get("skill_capsule_receipt_status")
            .and_then(Value::as_str)
        {
            summary["skill_capsule_receipt_status"] = Value::String(receipt_status.to_string());
        }
        if let Some(blocked_reason) = payload_obj.get("blocked_reason").and_then(Value::as_str) {
            summary["blocked_reason"] = Value::String(blocked_reason.to_string());
        }
        if let Some(failed_reason) = payload_obj.get("failed_reason").and_then(Value::as_str) {
            summary["failed_reason"] = Value::String(failed_reason.to_string());
        }
    }
    summary
}

fn trigger_observation_response(mut value: Value) -> Value {
    let summary = value.get("payload_summary").cloned();
    if let Some(summary) = summary.as_ref().and_then(Value::as_object) {
        if let Some(outcome_kind) = summary
            .get("skill_capsule_outcome_kind")
            .and_then(Value::as_str)
        {
            value["skill_capsule_outcome_kind"] = Value::String(outcome_kind.to_string());
        }
        if let Some(receipt_status) = summary
            .get("skill_capsule_receipt_status")
            .and_then(Value::as_str)
        {
            value["skill_capsule_receipt_status"] = Value::String(receipt_status.to_string());
        }
        if let Some(blocked_reason) = summary.get("blocked_reason").and_then(Value::as_str) {
            value["blocked_reason"] = Value::String(blocked_reason.to_string());
        }
        if let Some(failed_reason) = summary.get("failed_reason").and_then(Value::as_str) {
            value["failed_reason"] = Value::String(failed_reason.to_string());
        }
    }
    value
}

async fn internal_ingest_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(event_type): Path<String>,
    Json(body): Json<InternalIngestBody>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let event_id = format!("ievt_{}", ulid::Ulid::new().to_string().to_lowercase());
    state
        .db
        .enqueue_internal_event(
            &event_id,
            &event_type,
            body.source_workflow_id.as_deref(),
            body.source_run_id.as_deref(),
            &user.id,
            &body.payload,
        )
        .await
        .map_err(|e| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("enqueue_internal_event: {e}"),
            )
        })?;
    Ok(Json(serde_json::json!({
        "event_id": event_id,
        "event_type": event_type,
        "status": "queued",
    })))
}

// -- Triggers ------------------------------------------------------------------

async fn create_trigger_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<CreateTriggerRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let instance = state
        .db
        .get_master_agent_instance(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "no master agent".to_string()))?;
    let instance_id = instance["id"].as_str().unwrap_or("").to_string();
    let trigger_type = crate::agent_template::TriggerType::from_str(&body.trigger_type);
    let trigger = crate::agent_template::AgentTrigger::new(
        instance_id,
        user.id.clone(),
        trigger_type,
        body.config,
    );
    let id = trigger.id.clone();
    state
        .db
        .create_trigger(&trigger)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({"id": id})))
}

/// DELETE /agent/trigger/:id
async fn delete_trigger_http(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    state
        .db
        .delete_trigger(&user.id, &id)
        .await
        .map_err(trigger_delete_error_to_http)?;
    Ok(Json(serde_json::json!({"deleted": true})))
}

/// POST /agent/delegate
#[derive(serde::Deserialize)]
struct CreateDelegationRequest {
    scope: String,
    #[serde(default = "default_delegation_mask")]
    mask: String,
    #[serde(default = "default_delegation_expiry")]
    expires_in: u64,
}
fn default_delegation_mask() -> String {
    "private".to_string()
}
fn default_delegation_expiry() -> u64 {
    3600
}

// -- Delegations ---------------------------------------------------------------

async fn create_delegation_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<CreateDelegationRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    // GAP-111: enforce task-type / mask policy before issuing the delegation token.
    if !crate::policy_engine::PolicyEngine::can_run(&body.scope, &body.mask) {
        return Err((
            StatusCode::FORBIDDEN,
            format!(
                "delegation denied: task type '{}' is not allowed under mask '{}'",
                body.scope, body.mask
            ),
        ));
    }

    let instance = state
        .db
        .get_master_agent_instance(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "no master agent".to_string()))?;
    let instance_id = instance["id"].as_str().unwrap_or("").to_string();
    let master_key_hex = crate::agent_template::delegation_master_key_hex().map_err(|err| {
        tracing::error!(%err, "delegation issuance blocked by invalid master key");
        (StatusCode::SERVICE_UNAVAILABLE, err)
    })?;
    let task_id = Ulid::new().to_string();
    let delegation = crate::agent_template::generate_delegated_key(
        &master_key_hex,
        &body.scope,
        &task_id,
        body.expires_in,
        &instance_id,
        &user.id,
        vec![], // allowed_capabilities: resolved by orchestrator for workflow delegations
        vec![], // outbound_allowlist: resolved from compiled IR for workflow delegations
        None,   // context_snapshot: populated by orchestrator at delegation time
    );
    let id = delegation.id.clone();
    let expires_at = delegation.expires_at.to_rfc3339();
    state
        .db
        .create_delegation(&delegation)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({
        "id": id,
        "scope": body.scope,
        "mask": body.mask,
        "expires_at": expires_at,
    })))
}

