    #[test]
    fn internal_event_terminal_run_statuses_emit_correct_event_type() {
        let cases = [
            ("completed", "workflow_completed"),
            ("simulated", "workflow_completed"),
            ("failed", "workflow_failed"),
        ];
        for (status, expected_event) in &cases {
            let event_type = match *status {
                "failed" => "workflow_failed",
                _ => "workflow_completed",
            };
            assert_eq!(
                event_type, *expected_event,
                "status={status} should produce event_type={expected_event}"
            );
        }
        // Non-terminal statuses must not emit internal events.
        let non_terminal = ["in_progress", "waiting_for_approval", "blocked", "unknown"];
        for status in &non_terminal {
            assert!(
                !matches!(*status, "completed" | "failed" | "simulated"),
                "{status} is non-terminal and must not emit an internal event"
            );
        }
    }

