    #[test]
    fn resolve_scheduled_for_fixed_duration_returns_future_timestamp() {
        let descriptor = serde_json::json!({
            "delay": {
                "delay_kind": "fixed_duration",
                "duration_seconds": 300
            }
        });
        let result = super::resolve_scheduled_for(&descriptor, "2026-04-02T00:00:00Z", "timer");
        assert!(
            result.is_some(),
            "fixed_duration should produce a timestamp"
        );
        let ts = result.unwrap();
        let parsed = chrono::DateTime::parse_from_rfc3339(&ts).expect("valid RFC3339");
        let diff = parsed.timestamp() - chrono::Utc::now().timestamp();
        // Should be roughly 300 seconds in the future (allow ±30s for test execution time)
        assert!(
            diff > 260 && diff < 330,
            "diff={diff} not in expected range"
        );
    }

    #[test]
    fn resolve_scheduled_for_until_datetime_returns_literal() {
        let target = "2027-01-01T12:00:00Z";
        let descriptor = serde_json::json!({
            "delay": {
                "delay_kind": "until_datetime",
                "until_datetime": target
            }
        });
        let result = super::resolve_scheduled_for(&descriptor, "2026-04-02T00:00:00Z", "timer");
        assert_eq!(result.as_deref(), Some(target));
    }

    #[test]
    fn resolve_scheduled_for_approval_returns_none() {
        let descriptor = serde_json::json!({
            "delay": {
                "delay_kind": "fixed_duration",
                "duration_seconds": 600
            }
        });
        let result = super::resolve_scheduled_for(&descriptor, "2026-04-02T00:00:00Z", "approval");
        assert_eq!(result, None, "approval family must return None");
    }

    // -- Item 7: hybrid validation tests --------------------------------------

    #[test]
    fn validate_hybrid_trigger_valid_mode_passes() {
        let config: serde_json::Map<String, serde_json::Value> = serde_json::from_str(
            r#"{
            "trigger_family": "hybrid",
            "trigger_kind": "schedule",
            "time": { "schedule_kind": "cron", "cron_expression": "0 9 * * *" },
            "event": { "source_kind": "webhook", "webhook_path": "/hook" },
            "hybrid": { "continuation_mode": "event_then_time" }
        }"#,
        )
        .unwrap();
        let mut errors = Vec::new();
        let mut warnings = Vec::new();
        super::validate_workflow_trigger_config("node_h", &config, &mut errors, &mut warnings);
        assert!(
            errors.is_empty(),
            "valid hybrid mode should produce no errors; got: {errors:?}"
        );
    }

    #[test]
    fn validate_hybrid_trigger_unknown_mode_produces_error() {
        let config: serde_json::Map<String, serde_json::Value> = serde_json::from_str(
            r#"{
            "trigger_family": "hybrid",
            "trigger_kind": "schedule",
            "time": { "schedule_kind": "cron", "cron_expression": "0 9 * * *" },
            "event": { "source_kind": "webhook", "webhook_path": "/hook" },
            "hybrid": { "continuation_mode": "made_up_mode" }
        }"#,
        )
        .unwrap();
        let mut errors = Vec::new();
        let mut warnings = Vec::new();
        super::validate_workflow_trigger_config("node_h2", &config, &mut errors, &mut warnings);
        assert!(
            errors
                .iter()
                .any(|e| e.contains("unsupported hybrid continuation_mode")),
            "unknown mode should produce an error; errors={errors:?}"
        );
    }

